window.QK={"1":{"n":1,"name":"الفاتحة","t":["بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ","ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ","مَٰلِكِ يَوۡمِ ٱلدِّينِ","إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ","ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ","صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ"],"g":1,"a":[["light","🤲","نبدأ باسم الله، وهو الرحمن الرحيم الذي يرحمنا كثيرًا."],["earth","🌍","نحمد الله ونشكره، فهو ربّ كل شيء: الناس والحيوانات والسماء والأرض."],["light","💖","الله رحمته كبيرة جدًا، وتشمل كل شيء."],["light","⚖️","الله هو الملك يوم القيامة، يوم يجازي كل إنسان على عمله."],["mosque","🙏","يا الله، نعبدك وحدك، ونطلب المساعدة منك وحدك."],["light","🛤️","يا الله، دُلّنا على الطريق الصحيح، طريق الإسلام."],["garden","🌟","طريق الصالحين الذين أنعم الله عليهم، لا طريق الذين غضب عليهم ولا الذين ضلّوا."]],"i":"أعظم سورة في القرآن، وتُسمّى أمّ الكتاب والسبع المثاني. نقرؤها في كل ركعة من صلاتنا. فيها حمد الله والثناء عليه، والدعاء بأن يهدينا الطريق المستقيم.","l":["الفاتحة أعظم سورة، نقرؤها في كل ركعة","نحمد الله على نعمه الكثيرة","نعبد الله وحده ونطلب منه المساعدة","ندعو الله أن يهدينا الطريق المستقيم"],"q":[["كم مرة نقرأ الفاتحة في الصلاة؟",["في كل ركعة","مرة في اليوم","مرة في الأسبوع"]],["ما اسم آخر لسورة الفاتحة؟",["أمّ الكتاب","سورة الناس","سورة البقرة"]],["ماذا نطلب من الله في الفاتحة؟",["أن يهدينا الصراط المستقيم","المال","الألعاب"]]],"m":"اقرأ الفاتحة بقلبك في كل صلاة، فهي حديث بينك وبين الله.","type":"meccan"},"114":{"n":114,"name":"الناس","t":["قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ","مَلِكِ ٱلنَّاسِ","إِلَٰهِ ٱلنَّاسِ","مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ","ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ","مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ"],"g":6231,"a":[["light","🤲","قل: أحتمي بالله ربّ الناس."],["light","👑","ملك الناس."],["mosque","🙏","إله الناس الذي يعبدونه."],["night","😈💨","من شرّ الشيطان الذي يوسوس، ويختفي إذا ذكرنا الله."],["light","💭","الذي يوسوس في قلوب الناس."],["light","👥","سواء كان من الجن أو من الناس."]],"i":"سورة الناس آخر سورة في القرآن، وهي من المعوّذتين. نطلب فيها من الله أن يحمينا من وسوسة الشيطان.","l":["الله ربّ الناس وملكهم وإلههم","الشيطان يوسوس ويختفي إذا ذكرنا الله","نقرأ سورة الناس لنحتمي بالله"],"q":[["ماذا يفعل الشيطان إذا ذكرنا الله؟",["يختفي","يقترب","يضحك"]],["سورة الناس هي آخر سورة في...",["القرآن","جزء تبارك","سورة البقرة"]]],"m":"اذكر الله دائمًا، فيهرب الشيطان.","type":"meccan","x":{"1":{"mn":"أطلب الحماية من ربّ الناس.","tb":"نقول: يا رب احمِنا.","id":"طفل يدعو ربه ويطلب الحماية."},"2":{"mn":"الله هو الملك.","tb":"ربنا هو اللي يحكم كل شيء.","id":"تاج يرمز لملك كل الملوك."},"3":{"mn":"الله هو الإله الذي نعبده.","tb":"نعبد الله وحده ولا نعبد غيره.","id":"طفل يصلّي لله وحده."},"4":{"mn":"نحتمي من شرّ الشيطان الذي يوسوس ويختفي.","tb":"الشيطان يهمس ثم يختفي.","id":"الشيطان يوسوس في أذن الطفل ثم يختفي."},"5":{"mn":"يُدخل الشكوك والأفكار السيئة في قلوب الناس.","tb":"أفكار غلط تزعجنا.","id":"طفل يفكّر وفي قلبه أفكار سيئة."},"6":{"mn":"الشر ممكن يكون من الجن أو من الناس.","tb":"في ناس كمان ممكن تؤذي.","id":"الشر قد يأتي من الجن أو من بعض الناس."}},"imp":"استعذ بالله من كل شر 💖 تقرأها كل يوم لحمايتنا: في الصباح والمساء وقبل النوم. احفظها.. وكرّرها كل يوم لتحمي نفسك وأهلك.","pick":{"q":"لما نخاف أو نشعر بالضيق، ماذا نفعل؟","o":[["أقول السورة","a3",true],["أصرخ","a2",false],["ألعب","a1",false]]},"chk":{"q":"ضع علامة ✓ أمام ما يحافظ علينا من كل شر:","o":[["قراءة سورة الناس",true],["ترك الصلاة",false],["ذكر الله",true],["الوسوسة",false]]}},"113":{"n":113,"name":"الفلق","t":["قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ","مِن شَرِّ مَا خَلَقَ","وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","وَمِن شَرِّ ٱلنَّفَّـٰثَٰتِ فِي ٱلۡعُقَدِ","وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ"],"g":6226,"a":[["dawn","🌅","قل: أحتمي بالله ربّ الصباح."],["light","🛡️","من شرّ كل ما خلق."],["night","🌙","ومن شرّ الليل إذا أظلم."],["night","🪢","ومن شرّ السحرة الذين ينفثون في العُقَد."],["desert","😠","ومن شرّ الحسود إذا حسد."]],"i":"سورة الفلق وسورة الناس هما المعوّذتان. علّمنا النبي ﷺ أن نقرأهما في الصباح والمساء وقبل النوم، لنحتمي بالله من كل شر.","l":["نحتمي بالله من كل شر","نقرأ المعوّذتين في الصباح والمساء وقبل النوم","الحسد صفة سيئة"],"q":[["متى نقرأ المعوّذتين؟",["في الصباح والمساء وقبل النوم","مرة في السنة","لا نقرأهما"]],["بمن نحتمي من الشر؟",["بالله","بأنفسنا","بالأصدقاء"]]],"m":"احتمِ بالله كل يوم بقراءة المعوّذتين.","type":"meccan","x":{"1":{"mn":"أستعين بالله ربّ الصبح.","id":"أستعين بالله ربّ الصبح، الذي يضيء النهار ويمنحنا الحياة."},"2":{"mn":"من شرّ كلّ ما خلق الله.","id":"أطلب من الله الحماية من شرّ كلّ ما خلق، من إنسانٍ أو حيوانٍ أو شيءٍ آخر."},"3":{"mn":"من شرّ الليل إذا أظلم.","id":"أستعيذ بالله من شرّ الليل إذا أظلم وأخاف الناس فيه."},"4":{"mn":"ومن شرّ الساحرات اللاتي ينفثن في عقد الخيوط.","id":"أستعيذ بالله من شرّ الساحرات اللاتي يعملن السحر!"},"5":{"mn":"ومن شرّ الحاسد عندما يحسد.","id":"أستعيذ بالله من شرّ الحاسد عندما يحسد الناس على نعمة من الله عليهم."}},"imp":"سورة قصيرة من القرآن الكريم، تتحدث عن الاستعاذة بالله من كل شرّ في الدنيا. وأهم درس نتعلّمه منها: أن نستعين بالله دائمًا، فهو وحده القادر على حمايتنا من كلّ شرّ في الدنيا 💖"},"112":{"n":112,"name":"الإخلاص","t":["قُلۡ هُوَ ٱللَّهُ أَحَدٌ","ٱللَّهُ ٱلصَّمَدُ","لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ","وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ"],"g":6222,"a":[["light","☝️","قل: الله واحد، ليس له شريك."],["light","🌟","الله هو الذي يحتاجه كل شيء، وهو لا يحتاج أحدًا."],["light","🚫","الله ليس له أولاد، وليس له أب ولا أم."],["light","💎","ولا يوجد أحد مثل الله أبدًا."]],"i":"سأل المشركون النبي ﷺ: صِف لنا ربك. فأنزل الله هذه السورة. وهي تعدل ثلث القرآن في الأجر!","l":["الله واحد لا شريك له","سورة الإخلاص تعدل ثلث القرآن","لا أحد مثل الله"],"q":[["سورة الإخلاص تعدل كم من القرآن؟",["ثلث القرآن","نصف القرآن","كل القرآن"]],["هل لله ولد؟",["لا","نعم"]]],"m":"قل: هو الله أحد، وأحبّ قراءتها كل يوم.","type":"meccan","x":{"1":{"mn":"أخبرنا الله أنه واحدٌ في ذاته، لا شريك له."},"2":{"mn":"الله الذي لا يحتاج إلى أحد، والكلّ يحتاج إليه."},"3":{"mn":"الله لم يلد أحدًا، ولم يولد منه أحد."},"4":{"mn":"وليس هناك أحدٌ يساوي الله أو يشبهه في صفاته.","id":"الله: لا مثيل له ولا شبيه له."}},"chk":{"q":"متى نقرأ سورة الإخلاص؟ ضع علامة ✓","o":[["في الفجر والمساء",true],["قبل النوم",true],["بعد الصلاة",true],["مرة واحدة في السنة فقط",false]]},"cards":[["💡 فائدة السورة","تُعلّمنا أن الله واحد لا شريك له، فنعبده وحده ونحبّه ونثق به دائمًا.",""],["⭐ من فضائلها","• تعادل قراءة ثلث القرآن.\n• تحمي من الشرك.\n• تجلب البركة والطمأنينة.","c1"],["🌙 متى تقرأها؟","• في الفجر والمساء.\n• قبل النوم.\n• بعد الصلاة.\n• في كل وقت.","c2"],["💜 احفظها في قلبك","الله واحد لا شريك له، أعبده وحدي وأحبّه وأثق به.","c3"]]},"111":{"n":111,"name":"المسد","t":["تَبَّتۡ يَدَآ أَبِي لَهَبٖ وَتَبَّ","مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ","سَيَصۡلَىٰ نَارٗا ذَاتَ لَهَبٖ","وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ","فِي جِيدِهَا حَبۡلٌ مِّن مَّسَدِۭ"],"g":6217,"a":[["fire","🔥","خسر أبو لهب وهلك، لأنه كان يؤذي النبي ﷺ."],["desert","💰","لم ينفعه ماله ولا ما كسبه."],["fire","🔥","سيدخل نارًا لها لهب."],["desert","🌵","وزوجته أيضًا، التي كانت تضع الشوك في طريق النبي ﷺ لتؤذيه."],["desert","🪢","وفي رقبتها حبل قوي من ليف."]],"i":"أبو لهب هو عمّ النبي ﷺ، لكنه كان يؤذيه ويكذّبه. لما جمع النبي ﷺ قريشًا ليدعوهم إلى الإسلام، قال أبو لهب: تبًّا لك! وكانت زوجته أم جميل تضع الشوك في طريق النبي ﷺ. فنزلت السورة.","l":["إيذاء الناس نهايته الخسارة","المال لا ينفع من يعصي الله","القرابة لا تنفع بلا إيمان"],"q":[["من هو أبو لهب؟",["عمّ النبي ﷺ الذي آذاه","صديق النبي ﷺ","ملك"]],["ماذا كانت تفعل زوجته؟",["تضع الشوك في طريق النبي ﷺ","تطبخ له","تساعده"]]],"m":"لا تؤذِ أحدًا، فالإيذاء نهايته الخسارة.","type":"meccan","x":{"1":{"mn":"هلك وخسر أبو لهب لأنه كان بيؤذي النبي ﷺ."},"2":{"mn":"فلوسه وكل اللي عنده ما نفعتوش ولا حمته."},"3":{"mn":"هيتعاقب في نار شديدة بسبب أفعاله السيئة."},"4":{"mn":"زوجته كانت بتساعده في الأذى، زي اللي بيجمع حطب."},"5":{"mn":"في رقبتها حبل خشن كعقاب."}},"chk":{"q":"ضع علامة ✓ أمام الأخلاق الطيبة:","o":[["ما نأذيش حد",true],["نساعد غيرنا",true],["نؤذي الناس",false],["الفلوس أهم من الأخلاق",false]]},"cards":[["🧠 فكرة السورة ببساطة","السورة بتحكي عن شخص كان يؤذي النبي ﷺ: أبو لهب وزوجته. اللي يعمل شر نهايته مش كويسة.","c1"],["💡 الدروس المستفادة للأطفال","✅ ما نأذيش حد\n✅ نكون طيبين ونساعد غيرنا\n✅ الفلوس مش أهم حاجة، الأخلاق أهم\n✅ اللي يعمل شر، ربنا بيحاسبه",""]]},"110":{"n":110,"name":"النصر","t":["إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ","وَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجٗا","فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا"],"g":6214,"a":[["mosque","🏆🕋","إذا جاء نصر الله، وفتح المسلمون مكة."],["mosque","👨‍👩‍👧‍👦","ورأيت الناس يدخلون في الإسلام جماعات كثيرة."],["light","🤲","فسبّح الله واحمده، واطلب منه المغفرة، فالله يقبل التوبة."]],"i":"نزلت في آخر حياة النبي ﷺ، تبشّره بنصر الله وفتح مكة، ودخول الناس في الإسلام جماعات كثيرة، وتأمره بالتسبيح والاستغفار.","l":["النصر من عند الله","نشكر الله بالتسبيح والاستغفار عند النجاح"],"q":[["ماذا يدخل الناس أفواجًا؟",["دين الله","السوق","البحر"]],["ماذا نقول عند النجاح؟",["سبحان الله والحمد لله، ونستغفر الله","لا شيء","نتكبّر"]]],"m":"إذا نجحت، فاحمد الله واستغفره.","type":"medinan","x":{"1":{"mn":"إذا جاء نصر الله للمسلمين، وفتح الله مكة."},"2":{"mn":"ورأيت الناس يدخلون في الإسلام جماعات كثيرة."},"3":{"mn":"فاشكر الله وسبّحه، واطلب منه المغفرة؛ لأنه يقبل توبة عباده دائمًا."}},"chk":{"q":"ماذا نفعل عند الفرح والنجاح؟ ضع علامة ✓","o":[["نشكر الله",true],["نستغفر الله",true],["نتكبّر على الناس",false],["ننسى الله",false]]},"cards":[["🌸 الفكرة العامة","تبيّن السورة أن النصر والنجاح من عند الله، وتعلّمنا شكر الله والاستغفار عند الفرح والنجاح.",""]]},"109":{"n":109,"name":"الكافرون","t":["قُلۡ يَـٰٓأَيُّهَا ٱلۡكَٰفِرُونَ","لَآ أَعۡبُدُ مَا تَعۡبُدُونَ","وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ","وَلَآ أَنَا۠ عَابِدٌ مَّا عَبَدتُّمۡ","وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ","لَكُمۡ دِينُكُمۡ وَلِيَ دِينِ"],"g":6208,"a":[["desert","📢","قل يا محمد ﷺ للكافرين:"],["desert","🙅","أنا لا أعبد الأصنام التي تعبدونها."],["desert","🙅‍♂️","وأنتم لا تعبدون الله الذي أعبده."],["desert","✋","ولن أعبد أبدًا ما عبدتم."],["desert","✋","وأنتم لا تعبدون ما أعبد."],["mosque","☝️","لكم دينكم، ولي ديني: الإسلام."]],"i":"عرض بعض المشركين على النبي ﷺ أن يعبد آلهتهم سنة، ويعبدوا الله سنة! فأنزل الله هذه السورة: لا نعبد إلا الله، ولا نخلط ديننا بغيره.","l":["نعبد الله وحده ولا نشرك به شيئًا","نثبت على ديننا الإسلام"],"q":[["ماذا طلب المشركون من النبي ﷺ؟",["أن يعبد آلهتهم","أن يسافر","أن يبني بيتًا"]],["ما ديننا؟",["الإسلام","لا دين","كل الأديان معًا"]]],"m":"اثبت على عبادة الله وحده.","type":"meccan","x":{"1":{"mn":"يقول الله لنبيه محمد ﷺ: قل يا محمد للمشركين."},"2":{"mn":"أنا لا أعبد الأصنام التي تعبدونها."},"3":{"mn":"وأنتم لن تعبدوا الله الذي أعبده."},"4":{"mn":"وأنا لن أعبد ما تعبدونه من دون الله."},"5":{"mn":"ولن تعبدوا أنتم ما أعبده أبدًا."},"6":{"mn":"لكم دينكم الذي تختارونه، ولي ديني الذي اخترته، وهو الإسلام.","id":"الإسلام ديني وأفتخر 💖"}},"imp":"سورة قصيرة تعلّمنا الإخلاص والثبات على ديننا 💖","chk":{"q":"ضع علامة ✓ أمام ما نتعلّمه من سورة الكافرون:","o":[["نحب ديننا ونعتز به",true],["نحترم الآخرين",true],["نثبت على الحق",true],["نترك ديننا",false]]},"cards":[["🌟 ما نتعلّمه من السورة","💗 نحب ديننا ونعتز به.\n👥 نحترم الآخرين ولا نُجبرهم على ديننا.\n⭐ نكون ثابتين على الحق.\n📗 الإخلاص لله وحده.",""],["💖 سورة صغيرة معناها كبير","احفظها وعلّمها لغيرك.\nلنحفظها ونعمل بها كل يوم.","c1"]]},"108":{"n":108,"name":"الكوثر","t":["إِنَّآ أَعۡطَيۡنَٰكَ ٱلۡكَوۡثَرَ","فَصَلِّ لِرَبِّكَ وَٱنۡحَرۡ","إِنَّ شَانِئَكَ هُوَ ٱلۡأَبۡتَرُ"],"g":6205,"a":[["garden","🏞️💧","يا محمد ﷺ، أعطاك الله الكوثر، وهو نهر في الجنة فيه خير كثير."],["mosque","🙏","فصلِّ لله وحده، واذبح الأضحية لله شكرًا له."],["desert","🚫","والذي يكرهك هو المقطوع من كل خير."]],"i":"كان بعض المشركين يقولون عن النبي ﷺ إنه أبتر، أي لن يبقى له ذِكر، لأن أبناءه الذكور ماتوا وهم صغار. فأنزل الله هذه السورة: أعطاه الكوثر، نهرًا في الجنة، وأخبره أن الذي يبغضه هو المقطوع من الخير.","l":["الكوثر نهر في الجنة أعطاه الله للنبي ﷺ","نصلّي لله ونذبح لله وحده","من يحب النبي ﷺ يذكره بخير"],"q":[["ما هو الكوثر؟",["نهر في الجنة","جبل","مدينة"]],["لمن نصلّي؟",["لله وحده","للناس","لا أحد"]]],"m":"صلِّ لله، وأحِبّ النبي ﷺ.","type":"meccan","x":{"1":{"mn":"أي إنّا أعطيناك يا محمد ﷺ خيرًا كثيرًا في الدنيا والآخرة، وهو نهر في الجنة اسمه الكوثر، وعدد لا يُحصى من النعم."},"2":{"mn":"أي فصلِّ عبادتك كلها لربك وحده لا شريك له، واحرص على الذبح تقرّبًا إليه وشكرًا على نعمه."},"3":{"mn":"أي إنّ الذي يبغضك يا محمد ﷺ ويؤذيك، هو الذي لا خير فيه، ولا يبقى له ذِكر بعده."}}},"107":{"n":107,"name":"الماعون","t":["أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ","فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ","وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","فَوَيۡلٌ لِّلۡمُصَلِّينَ","ٱلَّذِينَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ","ٱلَّذِينَ هُمۡ يُرَآءُونَ","وَيَمۡنَعُونَ ٱلۡمَاعُونَ"],"g":6198,"a":[["desert","❓","هل تعرف الذي يكذّب بيوم الحساب؟"],["desert","🧒💔","هو الذي يدفع اليتيم بقسوة ولا يرحمه."],["desert","🍲","ولا يشجّع الناس على إطعام المسكين."],["mosque","⚠️","فالويل للمصلّين…"],["mosque","⏰","الذين يتهاونون في صلاتهم ويؤخرونها عن وقتها."],["desert","👀","الذين يعملون الخير ليراهم الناس فقط."],["garden","🧂🍽️","ويمنعون إعارة الأشياء البسيطة للناس، مثل الإناء والملح."]],"i":"سورة تحذّرنا من صفات سيئة: التكذيب بيوم الحساب، وقسوة القلب على اليتيم، وعدم الاهتمام بالمسكين، والتهاون في الصلاة، والرياء، ومنع مساعدة الناس في الأشياء البسيطة.","l":["نرحم اليتيم ونطعم المسكين","نصلّي في الوقت","نعمل الخير لله، لا ليرانا الناس","نساعد جيراننا ولو بشيء بسيط"],"q":[["كيف نعامل اليتيم؟",["برحمة وإكرام","بقسوة","نتجاهله"]],["متى نصلّي؟",["في وقتها","متى ما تذكرنا","لا نصلّي"]],["ما هو الماعون؟",["الأشياء البسيطة التي نعيرها للناس","الذهب","الطعام الكثير"]]],"m":"كن رحيمًا، وحافظ على صلاتك، وساعد غيرك.","type":"meccan","x":{"1":{"mn":"يعني: أتدري من هو الإنسان الذي لا يؤمن بالله ولا باليوم الآخر؟"},"2":{"mn":"هو الذي يطردُ اليتيم ولا يهتمّ به ولا يعامله بلطف."},"3":{"mn":"ولا يُشجّع الآخرين على إطعام الفقير أو يساعدهم على ذلك."},"4":{"mn":"فهلاكٌ وشرٌّ لأولئك الذين يُصلّون ولكن…"},"5":{"mn":"هم لا يُركّزون في صلاتهم، قلوبهم مشغولة بغير الله."},"6":{"mn":"هم يُصلّون ليَراهم الناس فقط، وليس حبًّا في الله."},"7":{"mn":"وهم يمنعون الأشياء الصغيرة النافعة للناس، ولا يحبّون مساعدة الآخرين."}},"chk":{"q":"ضع علامة ✓ أمام ما يحبّه الله:","o":[["أساعد اليتيم",true],["أصلّي بتركيز",true],["أصلّي ليراني الناس فقط",false],["أمنع جيراني من الأشياء الصغيرة",false]]},"cards":[["🌸 الخلاصة","⭐ ربنا يحبّ من يؤمن به ويعامل الآخرين بلطف.\n⭐ ساعد اليتيم، وأطعم الفقير، وكن نافعًا للناس.\n⭐ صلِّ بتركيز وإخلاص لله، ولا تُراءِ الناس.\n⭐ حتى الأشياء الصغيرة لها أجر كبير عند الله.","c1"]]},"106":{"n":106,"name":"قريش","t":["لِإِيلَٰفِ قُرَيۡشٍ","إِۦلَٰفِهِمۡ رِحۡلَةَ ٱلشِّتَآءِ وَٱلصَّيۡفِ","فَلۡيَعۡبُدُواْ رَبَّ هَٰذَا ٱلۡبَيۡتِ","ٱلَّذِيٓ أَطۡعَمَهُم مِّن جُوعٖ وَءَامَنَهُم مِّنۡ خَوۡفِۭ"],"g":6194,"a":[["desert","🐪🐪","انظروا إلى نعمة الله على قبيلة قريش، جعلهم يألفون الرحلات."],["desert","❄️☀️","رحلة في الشتاء إلى اليمن، ورحلة في الصيف إلى الشام، للتجارة."],["mosque","🕋","فليعبدوا ربّ هذا البيت، وهو الكعبة."],["garden","🍞🛡️","الله الذي أطعمهم فلم يجوعوا، وأمّنهم فلم يخافوا."]],"i":"كانت قبيلة قريش تسكن مكة، وتقوم برحلتين للتجارة كل سنة: رحلة الشتاء إلى اليمن، ورحلة الصيف إلى الشام، وكانوا آمنين لأنهم جيران الكعبة. فذكّرهم الله بنعمته وأمرهم أن يعبدوه.","l":["الطعام والأمان نعمتان عظيمتان من الله","نشكر الله بعبادته"],"q":[["إلى أين كانت رحلة الشتاء؟",["اليمن","الشام","مصر"]],["ماذا أعطى الله قريشًا؟",["الطعام والأمان","الحرب","الجوع"]]],"m":"اشكر الله على الطعام والأمان بعبادته.","type":"meccan","x":{"1":{"mn":"لألفة قريش واتحادهم."},"2":{"mn":"لأمانهم في رحلتي الشتاء والصيف للتجارة."},"3":{"mn":"فليشكروا الله ويعبدوه وحده، ربَّ هذا البيت الحرام."},"4":{"mn":"الذي أطعمهم عندما جاعوا، وأمّنهم عندما خافوا."}},"imp":"خلاصة السورة: الله أنعم على قريش بالألفة والأمن، ورزقهم من رحلتي الشتاء والصيف. فلنشكر الله ونعبده وحده.","chk":{"q":"كيف نطبّق سورة قريش؟ ضع علامة ✓","o":[["أشكر الله على نعمه كل يوم",true],["أكسب رزقي بالحلال",true],["أحافظ على بلادي",true],["أنسى نعم الله",false]]},"cards":[["💬 ما معنى السورة؟","تتحدث السورة عن نعمتين عظيمتين أنعم الله بهما على قريش:\n🐪 الرحلات في الصيف والشتاء للتجارة وكسب الرزق.\n🕋 الأمن في مكة ليعبدوا الله آمنين.","c1"],["🌿 فوائد السورة","❤️ تذكّرنا بنعمتي الأمن والرزق.\n🕋 تحثّنا على شكر الله على نعمه.\n🤲 تدلّنا على أن نعبد الله وحده.\n👥 تعلّمنا أن نعتمد على الله في كل أمورنا.",""],["🌍 كيف نطبّق السورة في حياتنا؟","• أشعر بالأمان في بلادي وأحافظ عليها.\n• أعمل بجدّ وأكسب رزقي بالحلال.\n• أزور بيت الله الحرام إن استطعت.\n• أشكر الله على نعمه كل يوم.","c2"],["🌼 تذكّر","الله هو الذي يطعمنا ويؤمّننا، فلنشكره دائمًا على كل نعمة.\nاشكر الله على نعمه الكثيرة، وقل دائمًا: الحمد لله رب العالمين.",""]]},"105":{"n":105,"name":"الفيل","t":["أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ","أَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِي تَضۡلِيلٖ","وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ","تَرۡمِيهِم بِحِجَارَةٖ مِّن سِجِّيلٖ","فَجَعَلَهُمۡ كَعَصۡفٖ مَّأۡكُولِۭ"],"g":6189,"a":[["desert","🐘⚔️","ألم تعرف ماذا فعل الله بأصحاب الفيل الذين جاؤوا ليهدموا الكعبة؟"],["mosque","🕋🛡️","أفشل الله خطتهم، فلم يستطيعوا هدم الكعبة."],["sky","🐦🐦🐦","وأرسل الله عليهم طيورًا كثيرة، جاءت جماعات جماعات."],["sky","🐦🪨","كانت الطيور ترميهم بحجارة صغيرة من طين قاسٍ."],["desert","🍂","فصاروا مثل ورق الزرع الذي أكلته الحيوانات."]],"i":"قبل ولادة النبي ﷺ بقليل، جاء ملك اسمه أبرهة من اليمن بجيش كبير ومعه فيل ضخم، يريد أن يهدم الكعبة. فلما اقتربوا من مكة، رفض الفيل أن يتقدّم نحو الكعبة، وأرسل الله عليهم طيورًا تحمل حجارة صغيرة فأهلكتهم. وسُمّي ذلك العام: عام الفيل، وفيه وُلد النبي ﷺ.","l":["الله يحمي بيته الحرام","الله قادر على كل شيء مهما كان الأعداء أقوياء","الظلم نهايته الخسارة"],"q":[["من أراد أن يهدم الكعبة؟",["أبرهة وجيشه","قريش","أهل المدينة"]],["ماذا أرسل الله على الجيش؟",["طيرًا أبابيل","مطرًا","ريحًا"]],["ماذا سُمّي ذلك العام؟",["عام الفيل","عام الحزن","عام الفتح"]]],"m":"ثق بالله، فهو القوي القادر على كل شيء.","type":"meccan"},"104":{"n":104,"name":"الهمزة","t":["وَيۡلٌ لِّكُلِّ هُمَزَةٖ لُّمَزَةٍ","ٱلَّذِي جَمَعَ مَالٗا وَعَدَّدَهُۥ","يَحۡسَبُ أَنَّ مَالَهُۥٓ أَخۡلَدَهُۥ","كَلَّاۖ لَيُنۢبَذَنَّ فِي ٱلۡحُطَمَةِ","وَمَآ أَدۡرَىٰكَ مَا ٱلۡحُطَمَةُ","نَارُ ٱللَّهِ ٱلۡمُوقَدَةُ","ٱلَّتِي تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ","إِنَّهَا عَلَيۡهِم مُّؤۡصَدَةٌ","فِي عَمَدٖ مُّمَدَّدَةِۭ"],"g":6180,"a":[["desert","🗣️👉","الويل لكل من يعيب الناس ويغتابهم ويسخر منهم."],["desert","💰","الذي جمع المال وعدّه مرة بعد مرة."],["desert","💰⏳","يظن أن ماله سيبقيه حيًا للأبد."],["fire","🔥","كلا، ليُطرحنّ في الحُطَمة."],["fire","❓","وما أدراك ما الحُطَمة؟"],["fire","🔥","هي نار الله المشتعلة."],["fire","💓","التي يصل حرّها إلى القلوب."],["fire","🔒","إنها مغلقة عليهم، بأعمدة ممدودة طويلة.",2],["fire","🔒","إنها مغلقة عليهم، بأعمدة ممدودة طويلة.",-1]],"i":"سورة مكية تحذّر من الذي يعيب الناس ويغتابهم ويستهزئ بهم، ومن الذي يجمع المال ويظن أنه سيبقيه حيًا للأبد.","l":["لا نسخر من الناس ولا نغتابهم","المال لا يجعل الإنسان يعيش للأبد","الكلام الطيب يحبه الله"],"q":[["ماذا يفعل الهمزة اللمزة؟",["يعيب الناس ويسخر منهم","يساعد الناس","يصلّي"]],["هل المال يجعل الإنسان يعيش للأبد؟",["لا","نعم","أحيانًا"]]],"m":"احفظ لسانك عن السخرية والغيبة.","type":"meccan"},"103":{"n":103,"name":"العصر","t":["وَٱلۡعَصۡرِ","إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ","إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ"],"g":6177,"a":[["dawn","⏳","الله يُقسم بالعصر، وهو الوقت والزمن."],["desert","😟","كل الناس في خسارة…"],["garden","🤝","إلا الذين آمنوا بالله، وعملوا الأعمال الطيبة، ونصح بعضهم بعضًا بالحق وبالصبر."]],"i":"سورة قصيرة عظيمة، قال الإمام الشافعي: لو ما أنزل الله حجة على خلقه إلا هذه السورة لكفتهم. تعلّمنا كيف ننجو من الخسارة.","l":["الوقت ثمين، فلا نضيّعه","طريق النجاة: الإيمان، والعمل الصالح، والتواصي بالحق والصبر"],"q":[["بماذا أقسم الله في سورة العصر؟",["بالعصر وهو الوقت","بالشمس","بالبحر"]],["كيف ننجو من الخسارة؟",["بالإيمان والعمل الصالح والتواصي بالحق والصبر","بالنوم","باللعب"]]],"m":"استغلّ وقتك في الخير.","type":"meccan"},"102":{"n":102,"name":"التكاثر","t":["أَلۡهَىٰكُمُ ٱلتَّكَاثُرُ","حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ","كَلَّا سَوۡفَ تَعۡلَمُونَ","ثُمَّ كَلَّا سَوۡفَ تَعۡلَمُونَ","كَلَّا لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡيَقِينِ","لَتَرَوُنَّ ٱلۡجَحِيمَ","ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ","ثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ"],"g":6169,"a":[["desert","💰💰","شغلكم التفاخر بكثرة المال والأولاد عن طاعة الله."],["desert","🪦","حتى متّم ودخلتم القبور."],["light","⚠️","كلا، سوف تعلمون عاقبة ذلك، ثم كلا سوف تعلمون.",2],["light","⚠️","كلا، سوف تعلمون عاقبة ذلك، ثم كلا سوف تعلمون.",-1],["light","🧠","لو تعلمون علمًا يقينًا ما انشغلتم بذلك."],["fire","👀🔥","لترونّ الجحيم، ثم لترونّها بأعينكم يقينًا.",2],["fire","👀🔥","لترونّ الجحيم، ثم لترونّها بأعينكم يقينًا.",-1],["light","🍎💧","ثم لتُسألنّ يومئذ عن كل نعمة أعطاكم الله."]],"i":"سورة تحذّرنا من الانشغال بجمع المال والتفاخر بكثرة الأولاد والأشياء حتى ننسى الآخرة، وتذكّرنا أننا سنُسأل عن كل نعمة.","l":["لا ننشغل بجمع الأشياء والتفاخر","سنُسأل عن كل نعمة: الطعام والماء والصحة","نستعمل النعم في طاعة الله"],"q":[["عن ماذا سنُسأل يوم القيامة؟",["عن النعيم","عن الطقس","لا شيء"]],["ما الذي شغل الناس في السورة؟",["التفاخر بكثرة المال والأولاد","الصلاة","القراءة"]]],"m":"كل نعمة عندك ستُسأل عنها، فاشكر الله عليها.","type":"meccan"},"101":{"n":101,"name":"القارعة","t":["ٱلۡقَارِعَةُ","مَا ٱلۡقَارِعَةُ","وَمَآ أَدۡرَىٰكَ مَا ٱلۡقَارِعَةُ","يَوۡمَ يَكُونُ ٱلنَّاسُ كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ","وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ٱلۡمَنفُوشِ","فَأَمَّا مَن ثَقُلَتۡ مَوَٰزِينُهُۥ","فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ","وَأَمَّا مَنۡ خَفَّتۡ مَوَٰزِينُهُۥ","فَأُمُّهُۥ هَاوِيَةٌ","وَمَآ أَدۡرَىٰكَ مَا هِيَهۡ","نَارٌ حَامِيَةُۢ"],"g":6158,"a":[["storm","🔔💥","القارعة: يوم القيامة الذي يقرع القلوب بأهواله."],["storm","❓","ما القارعة؟"],["storm","❓","وما أدراك ما القارعة؟"],["storm","🦋","يوم يكون الناس مثل الفراش المنتشر في كل مكان."],["mountain","🧶","وتكون الجبال مثل الصوف المنفوش."],["garden","⚖️😊","فأما من ثقلت موازين حسناته، فهو في عيشة راضية في الجنة.",2],["garden","⚖️😊","فأما من ثقلت موازين حسناته، فهو في عيشة راضية في الجنة.",-1],["fire","⚖️","وأما من خفّت موازين حسناته، فمكانه الهاوية.",2],["fire","⚖️","وأما من خفّت موازين حسناته، فمكانه الهاوية.",-1],["fire","❓","وما أدراك ما هي؟"],["fire","🔥","نار حامية شديدة الحرارة."]],"i":"سورة تصف يوم القيامة الذي يقرع القلوب بأهواله، ويوزن فيه عمل كل إنسان: من ثقلت حسناته ففي الجنة، ومن خفّت ففي النار.","l":["يوم القيامة تُوزن أعمالنا","نُكثر من الحسنات لتثقل موازيننا","الجنة عيشة راضية"],"q":[["كيف يكون الناس يوم القيامة؟",["مثل الفراش المبثوث","مثل الأسود","نائمين"]],["أين يذهب من ثقلت موازينه؟",["إلى عيشة راضية في الجنة","إلى النار","إلى البحر"]]],"m":"أكثِر من الحسنات لتثقل موازينك.","type":"meccan"},"100":{"n":100,"name":"العاديات","t":["وَٱلۡعَٰدِيَٰتِ ضَبۡحٗا","فَٱلۡمُورِيَٰتِ قَدۡحٗا","فَٱلۡمُغِيرَٰتِ صُبۡحٗا","فَأَثَرۡنَ بِهِۦ نَقۡعٗا","فَوَسَطۡنَ بِهِۦ جَمۡعًا","إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌ","وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ","وَإِنَّهُۥ لِحُبِّ ٱلۡخَيۡرِ لَشَدِيدٌ","۞أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِي ٱلۡقُبُورِ","وَحُصِّلَ مَا فِي ٱلصُّدُورِ","إِنَّ رَبَّهُم بِهِمۡ يَوۡمَئِذٖ لَّخَبِيرُۢ"],"g":6147,"a":[["desert","🐎💨","يُقسم الله بالخيل التي تجري بسرعة حتى يُسمع صوت أنفاسها."],["desert","🐎✨","التي تقدح الشرر بحوافرها على الحجارة."],["dawn","🐎🌅","التي تُغير على الأعداء وقت الصباح."],["desert","🌪️","فأثارت الغبار بجريها."],["desert","🐎🐎","فدخلت بفرسانها وسط جموع الأعداء."],["desert","😒","إن الإنسان لجحود لنعم ربه."],["light","👁️","وإنه على جحوده لشاهد."],["desert","💰","وإنه لحبّ المال شديد."],["desert","🪦","أفلا يعلم ماذا يحدث إذا أُخرج الموتى من القبور؟"],["light","💭🔍","وظهر ما في الصدور من خير أو شر؟"],["light","👁️","إن ربهم بهم يومئذ لخبير، يعلم كل شيء عنهم."]],"i":"سورة مكية يُقسم الله فيها بالخيل التي تجري بسرعة، ليُخبرنا أن الإنسان كثيرًا ما يجحد نعم ربه، ويحب المال حبًا شديدًا.","l":["نشكر الله على نعمه ولا ننكرها","لا نجعل حب المال أكبر من حب الله","الله يعلم ما في قلوبنا"],"q":[["بماذا أقسم الله في أول السورة؟",["بالخيل التي تجري","بالطيور","بالسمك"]],["ماذا يحب الإنسان حبًا شديدًا؟",["المال","النوم","الماء"]]],"m":"اشكر ربك على نعمه، واجعل قلبك نظيفًا.","type":"meccan"},"99":{"n":99,"name":"الزلزلة","t":["إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا","وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا","وَقَالَ ٱلۡإِنسَٰنُ مَا لَهَا","يَوۡمَئِذٖ تُحَدِّثُ أَخۡبَارَهَا","بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا","يَوۡمَئِذٖ يَصۡدُرُ ٱلنَّاسُ أَشۡتَاتٗا لِّيُرَوۡاْ أَعۡمَٰلَهُمۡ","فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ","وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ"],"g":6139,"a":[["earth","🌍💥","إذا زُلزلت الأرض زلزالها الشديد."],["earth","⛏️","وأخرجت الأرض ما في داخلها."],["desert","😲❓","وقال الإنسان متعجّبًا: ما لها؟"],["earth","🗣️🌍","يومئذ تتكلّم الأرض وتخبر بما عمل الناس عليها."],["light","☝️","لأن الله أمرها بذلك."],["light","👥📋","يومئذ يخرج الناس جماعات ليروا أعمالهم."],["light","🔬😊","فمن عمل خيرًا ولو بمقدار ذرة صغيرة جدًا يره."],["light","🔬😟","ومن عمل شرًا ولو بمقدار ذرة يره."]],"i":"سورة تصف زلزلة الأرض يوم القيامة، حين تُخرج ما في داخلها، وتتكلّم وتخبر بما عمل الناس فوقها. وتعلّمنا أن كل عمل، ولو كان صغيرًا مثل الذرّة، سنراه.","l":["الأرض ستشهد بما عملنا عليها","لا نحتقر أي عمل خير ولو كان صغيرًا","كل عمل سنراه يوم القيامة"],"q":[["ماذا تفعل الأرض يوم القيامة؟",["تتكلّم وتخبر بما عمل الناس","تنام","تطير"]],["هل نرى أعمالنا الصغيرة؟",["نعم، ولو مثقال ذرة","لا","فقط الكبيرة"]]],"m":"كل عمل خير صغير له قيمة عند الله، فلا تتركه.","type":"medinan"},"98":{"n":98,"name":"البينة","t":["لَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ","رَسُولٌ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفٗا مُّطَهَّرَةٗ","فِيهَا كُتُبٌ قَيِّمَةٌ","وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ","وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ","إِنَّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ فِي نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآۚ أُوْلَـٰٓئِكَ هُمۡ شَرُّ ٱلۡبَرِيَّةِ","إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أُوْلَـٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ","جَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ"],"g":6131,"a":[["desert","🤔","لم يكن الكفار من أهل الكتاب والمشركين تاركين كفرهم حتى تأتيهم الحجة الواضحة."],["light","📖✨","وهي رسول من الله، محمد ﷺ، يتلو صحفًا طاهرة."],["light","📜","فيها أحكام مستقيمة عادلة."],["desert","↔️","وما تفرّق أهل الكتاب إلا بعد ما جاءتهم الحجة الواضحة."],["mosque","🙏","وما أُمروا إلا ليعبدوا الله وحده مخلصين، ويقيموا الصلاة، ويؤتوا الزكاة، وذلك هو الدين المستقيم."],["fire","⚠️","إن الذين كفروا في نار جهنم خالدين، أولئك شرّ الخلق."],["garden","🌟","إن الذين آمنوا وعملوا الصالحات أولئك خير الخلق."],["garden","🌳💖","جزاؤهم عند ربهم جنات تجري تحتها الأنهار، رضي الله عنهم ورضوا عنه، وذلك لمن خشي ربه."]],"i":"سورة مدنية تخبرنا أن الله أرسل محمدًا ﷺ بالحجة الواضحة، يتلو صحفًا طاهرة، وأن الله أمرنا أن نعبده وحده بإخلاص، ونقيم الصلاة ونؤتي الزكاة.","l":["نعبد الله وحده بإخلاص","نقيم الصلاة ونؤتي الزكاة","المؤمنون الذين يعملون الصالحات هم خير الخلق"],"q":[["بماذا أُمرنا في هذه السورة؟",["نعبد الله ونقيم الصلاة ونؤتي الزكاة","نلعب","ننام"]],["من هم خير الخلق؟",["الذين آمنوا وعملوا الصالحات","الأغنياء","الأقوياء"]]],"m":"اعبد الله بإخلاص، لتكون من خير الخلق.","type":"medinan"},"97":{"n":97,"name":"القدر","t":["إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ","وَمَآ أَدۡرَىٰكَ مَا لَيۡلَةُ ٱلۡقَدۡرِ","لَيۡلَةُ ٱلۡقَدۡرِ خَيۡرٌ مِّنۡ أَلۡفِ شَهۡرٖ","تَنَزَّلُ ٱلۡمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرٖ","سَلَٰمٌ هِيَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ"],"g":6126,"a":[["night","🌙📖","إنا أنزلنا القرآن في ليلة القدر."],["night","❓✨","وما أدراك ما ليلة القدر؟"],["night","🌟🏆","ليلة القدر خير من ألف شهر."],["night","😇✨","تنزل الملائكة وجبريل فيها بإذن ربهم بكل أمر."],["dawn","🕊️🌅","هي ليلة سلام حتى طلوع الفجر."]],"i":"سورة تخبرنا عن ليلة القدر، الليلة المباركة التي نزل فيها القرآن في شهر رمضان. العبادة فيها أفضل من عبادة ألف شهر!","l":["القرآن نزل في ليلة القدر","ليلة القدر في رمضان، وهي خير من ألف شهر","نجتهد في العبادة والدعاء في العشر الأواخر من رمضان"],"q":[["ماذا نزل في ليلة القدر؟",["القرآن","المطر","الثلج"]],["ليلة القدر خير من كم شهر؟",["ألف شهر","شهر واحد","عشرة أشهر"]],["في أي شهر ليلة القدر؟",["رمضان","شوال","محرم"]]],"m":"اجتهد في رمضان لتنال بركة ليلة القدر.","type":"meccan"},"96":{"n":96,"name":"العلق","t":["ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ","خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ","ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ","ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ","عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ","كَلَّآ إِنَّ ٱلۡإِنسَٰنَ لَيَطۡغَىٰٓ","أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ","إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ","أَرَءَيۡتَ ٱلَّذِي يَنۡهَىٰ","عَبۡدًا إِذَا صَلَّىٰٓ","أَرَءَيۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰٓ","أَوۡ أَمَرَ بِٱلتَّقۡوَىٰٓ","أَرَءَيۡتَ إِن كَذَّبَ وَتَوَلَّىٰٓ","أَلَمۡ يَعۡلَم بِأَنَّ ٱللَّهَ يَرَىٰ","كَلَّا لَئِن لَّمۡ يَنتَهِ لَنَسۡفَعَۢا بِٱلنَّاصِيَةِ","نَاصِيَةٖ كَٰذِبَةٍ خَاطِئَةٖ","فَلۡيَدۡعُ نَادِيَهُۥ","سَنَدۡعُ ٱلزَّبَانِيَةَ","كَلَّا لَا تُطِعۡهُ وَٱسۡجُدۡۤ وَٱقۡتَرِب۩"],"g":6107,"a":[["mountain","📖⛰️","اقرأ باسم ربك الذي خلق كل شيء."],["light","🌱","خلق الإنسان من شيء صغير جدًا."],["light","📖✨","اقرأ، وربك هو الأكرم."],["light","✏️","الذي علّم الإنسان الكتابة بالقلم."],["light","🧠💡","علّم الإنسان ما لم يكن يعلم."],["desert","😤💰","لكن الإنسان يتكبّر ويتجاوز الحد إذا رأى نفسه غنيًا.",2],["desert","😤💰","لكن الإنسان يتكبّر ويتجاوز الحد إذا رأى نفسه غنيًا.",-1],["light","☝️","إن رجوع الجميع إلى ربك."],["mosque","🙏🚫","أرأيت الذي يمنع عبدًا إذا صلّى؟ (كان أبو جهل يمنع النبي ﷺ من الصلاة)",2],["mosque","🙏🚫","أرأيت الذي يمنع عبدًا إذا صلّى؟ (كان أبو جهل يمنع النبي ﷺ من الصلاة)",-1],["mosque","🧭","أرأيت إن كان هذا المصلّي على الهدى، أو أمر بالتقوى؟",2],["mosque","🧭","أرأيت إن كان هذا المصلّي على الهدى، أو أمر بالتقوى؟",-1],["desert","🚫","أرأيت إن كذّب الذي يمنعه وأعرض؟"],["light","👁️","ألم يعلم بأن الله يرى؟"],["storm","⚠️","لئن لم يتوقف، لنأخذنّه بناصيته، مقدّمة رأسه الكاذبة الخاطئة.",2],["storm","⚠️","لئن لم يتوقف، لنأخذنّه بناصيته، مقدّمة رأسه الكاذبة الخاطئة.",-1],["storm","😇💪","فليدعُ أصحابه لينصروه، سندعو الملائكة الأقوياء.",2],["storm","😇💪","فليدعُ أصحابه لينصروه، سندعو الملائكة الأقوياء.",-1],["mosque","🙇","لا تطعه، واسجد لله، واقترب منه."]],"i":"أول ما نزل من القرآن هو أول خمس آيات من هذه السورة. نزل جبريل عليه السلام على النبي ﷺ في غار حراء وقال له: اقرأ. فبدأ القرآن بالأمر بالقراءة والعلم. ثم تحكي السورة عن أبي جهل الذي كان يمنع النبي ﷺ من الصلاة.","l":["أول كلمة نزلت من القرآن: اقرأ، فالعلم مهم جدًا","القلم نعمة من الله نتعلّم به","الله يرى كل شيء","السجود يقرّبنا من الله"],"q":[["ما أول كلمة نزلت من القرآن؟",["اقرأ","اكتب","العب"]],["أين نزل أول القرآن؟",["في غار حراء","في البيت","في السوق"]],["متى نكون أقرب إلى الله؟",["في السجود","في النوم","في اللعب"]]],"m":"اقرأ وتعلّم، واسجد لله واقترب منه.","type":"meccan"},"95":{"n":95,"name":"التين","t":["وَٱلتِّينِ وَٱلزَّيۡتُونِ","وَطُورِ سِينِينَ","وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ","لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ","ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ","إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَلَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ","فَمَا يُكَذِّبُكَ بَعۡدُ بِٱلدِّينِ","أَلَيۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَٰكِمِينَ"],"g":6099,"a":[["garden","🫒🌳","يُقسم الله بالتين والزيتون."],["mountain","⛰️","وبجبل الطور الذي كلّم الله عليه موسى عليه السلام."],["mosque","🕋","وبهذا البلد الآمن: مكة."],["light","🧍✨","لقد خلقنا الإنسان في أحسن صورة وأجمل شكل."],["desert","⬇️","ثم يُردّ من لا يؤمن إلى أسفل الأماكن."],["garden","🎁","إلا الذين آمنوا وعملوا الصالحات فلهم أجر لا ينقطع."],["light","❓","فما الذي يجعلك تكذّب بيوم الحساب بعد هذا؟"],["light","⚖️","أليس الله أحكم الحاكمين؟ بلى."]],"i":"سورة مكية يُقسم الله فيها بالتين والزيتون وجبل الطور ومكة، ليخبرنا أنه خلق الإنسان في أحسن صورة.","l":["الله خلقنا في أحسن صورة فلنشكره","الإيمان والعمل الصالح سبب الأجر الدائم","الله أحكم الحاكمين"],"q":[["بماذا أقسم الله أول السورة؟",["بالتين والزيتون","بالتفاح","بالموز"]],["كيف خلق الله الإنسان؟",["في أحسن تقويم","بلا شكل","ضعيفًا دائمًا"]]],"m":"خلقك الله في أحسن صورة، فاشكره بالعمل الصالح.","type":"meccan"},"94":{"n":94,"name":"الشرح","t":["أَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ","وَوَضَعۡنَا عَنكَ وِزۡرَكَ","ٱلَّذِيٓ أَنقَضَ ظَهۡرَكَ","وَرَفَعۡنَا لَكَ ذِكۡرَكَ","فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا","إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا","فَإِذَا فَرَغۡتَ فَٱنصَبۡ","وَإِلَىٰ رَبِّكَ فَٱرۡغَب"],"g":6091,"a":[["light","💖✨","ألم نشرح لك صدرك ونجعله واسعًا مطمئنًا؟"],["light","🎒","ووضعنا عنك الحِمل الثقيل الذي كان يُتعب ظهرك.",2],["light","🎒","ووضعنا عنك الحِمل الثقيل الذي كان يُتعب ظهرك.",-1],["mosque","🕌📢","ورفعنا لك ذكرك، فيُذكر اسمك مع اسم الله في الأذان."],["dawn","🌈","فإن مع العسر يسرًا."],["dawn","🌈","إن مع العسر يسرًا (مرة ثانية للتأكيد)."],["mosque","🙏","فإذا انتهيت من عملك، فاجتهد في العبادة."],["light","🤲","وإلى ربك وحده فارغب واطلب."]],"i":"سورة مكية تذكّر النبي ﷺ بنعم الله عليه: شرح صدره، ورفع ذكره، وتعدنا جميعًا أن بعد كل صعوبة يأتي اليُسر.","l":["بعد كل صعوبة يأتي اليسر","الله يشرح صدور المؤمنين","اسم النبي ﷺ يُذكر في الأذان كل يوم"],"q":[["ماذا يأتي مع العسر؟",["اليسر","الحزن","التعب"]],["أين يُذكر اسم النبي ﷺ مع اسم الله؟",["في الأذان","في الألعاب","لا يُذكر"]]],"m":"لا تيأس أبدًا، فإن مع العسر يسرًا.","type":"meccan"},"93":{"n":93,"name":"الضحى","t":["وَٱلضُّحَىٰ","وَٱلَّيۡلِ إِذَا سَجَىٰ","مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","وَلَلۡأٓخِرَةُ خَيۡرٌ لَّكَ مِنَ ٱلۡأُولَىٰ","وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ فَتَرۡضَىٰٓ","أَلَمۡ يَجِدۡكَ يَتِيمٗا فَـَٔاوَىٰ","وَوَجَدَكَ ضَآلّٗا فَهَدَىٰ","وَوَجَدَكَ عَآئِلٗا فَأَغۡنَىٰ","فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ","وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ","وَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ"],"g":6080,"a":[["day","🌞","يُقسم الله بوقت الضحى، حين يرتفع ضوء الشمس."],["night","🌙","وبالليل إذا سكن وهدأ."],["light","💖","ما تركك ربك يا محمد ﷺ، وما أبغضك."],["garden","🌳","وللآخرة خير لك من الدنيا."],["garden","🎁😊","ولسوف يعطيك ربك حتى ترضى."],["light","🏠🤗","ألم يجدك يتيمًا فآواك ورعاك؟"],["light","🧭","ووجدك لا تعرف طريق الوحي فهداك."],["light","💰","ووجدك فقيرًا فأغناك."],["garden","🧒🤗","فأما اليتيم فلا تقهره، بل أكرمه."],["garden","🙂","وأما الذي يسألك ويطلب منك فلا تنهره."],["light","🗣️🎁","وأما نعمة ربك فتحدّث بها واشكرها."]],"i":"سورة مكية. تأخّر نزول الوحي على النبي ﷺ أيامًا فحزن، فقال المشركون: إن ربه تركه! فنزلت السورة تطمئنه بأن الله لم يتركه ولم يبغضه، وتذكّره بنعم الله عليه.","l":["الله لا يترك عباده المؤمنين","نُكرم اليتيم ولا نؤذيه","نتكلّم برفق مع من يطلب منا","نشكر الله على نعمه ونتحدّث بها"],"q":[["ماذا قال الله لنبيه ﷺ؟",["ما ودّعك ربك وما قلى","اتركني","لا تصلِّ"]],["كيف نعامل اليتيم؟",["لا نقهره ونكرمه","نصرخ عليه","نتجاهله"]],["ماذا نفعل بنعم الله؟",["نتحدّث بها ونشكرها","نخفيها","ننساها"]]],"m":"الله معك دائمًا، فلا تحزن، واشكره على نعمه.","type":"meccan"},"92":{"n":92,"name":"الليل","t":["وَٱلَّيۡلِ إِذَا يَغۡشَىٰ","وَٱلنَّهَارِ إِذَا تَجَلَّىٰ","وَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ","إِنَّ سَعۡيَكُمۡ لَشَتَّىٰ","فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ","وَصَدَّقَ بِٱلۡحُسۡنَىٰ","فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ","وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ","وَكَذَّبَ بِٱلۡحُسۡنَىٰ","فَسَنُيَسِّرُهُۥ لِلۡعُسۡرَىٰ","وَمَا يُغۡنِي عَنۡهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ","إِنَّ عَلَيۡنَا لَلۡهُدَىٰ","وَإِنَّ لَنَا لَلۡأٓخِرَةَ وَٱلۡأُولَىٰ","فَأَنذَرۡتُكُمۡ نَارٗا تَلَظَّىٰ","لَا يَصۡلَىٰهَآ إِلَّا ٱلۡأَشۡقَى","ٱلَّذِي كَذَّبَ وَتَوَلَّىٰ","وَسَيُجَنَّبُهَا ٱلۡأَتۡقَى","ٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ","وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ","إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ","وَلَسَوۡفَ يَرۡضَىٰ"],"g":6059,"a":[["night","🌑","يُقسم الله بالليل إذا غطّى الأرض بظلامه."],["day","☀️","وبالنهار إذا أضاء."],["garden","👫","وبخلق الذكر والأنثى."],["light","🛤️","إن أعمالكم مختلفة: منها الخير ومنها الشر."],["garden","🎁🛤️","فأما من أعطى واتّقى الله، وصدّق بالجنة، فسنيسّر له طريق الخير.",3],["garden","🎁🛤️","فأما من أعطى واتّقى الله، وصدّق بالجنة، فسنيسّر له طريق الخير.",-1],["garden","🎁🛤️","فأما من أعطى واتّقى الله، وصدّق بالجنة، فسنيسّر له طريق الخير.",-1],["desert","🔒💰","وأما من بخل واستغنى، وكذّب بالجنة، فسنيسّر له طريق الشر.",3],["desert","🔒💰","وأما من بخل واستغنى، وكذّب بالجنة، فسنيسّر له طريق الشر.",-1],["desert","🔒💰","وأما من بخل واستغنى، وكذّب بالجنة، فسنيسّر له طريق الشر.",-1],["desert","💸","ولن ينفعه ماله إذا مات."],["light","🧭","إن علينا أن نبيّن طريق الهدى."],["light","🌍","وإن لنا الدنيا والآخرة."],["fire","🔥","فأنذرتكم نارًا تتوهّج."],["fire","🔥","لا يدخلها إلا الأشقى، الذي كذّب وأعرض.",2],["fire","🔥","لا يدخلها إلا الأشقى، الذي كذّب وأعرض.",-1],["garden","🎁","وسيبتعد عنها الأتقى، الذي يعطي ماله ليطهّر نفسه.",2],["garden","🎁","وسيبتعد عنها الأتقى، الذي يعطي ماله ليطهّر نفسه.",-1],["light","❤️☝️","لا يعطي ليردّ معروفًا لأحد، بل يريد وجه ربه الأعلى.",2],["light","❤️☝️","لا يعطي ليردّ معروفًا لأحد، بل يريد وجه ربه الأعلى.",-1],["garden","😊","ولسوف يرضى بما يعطيه الله."]],"i":"سورة مكية تخبرنا أن الناس مختلفون في أعمالهم: منهم من يعطي ويتّقي الله فييسّر الله له الخير، ومنهم من يبخل فيصعب عليه طريق الخير. وتذكر المؤمن الذي يعطي ماله لله وحده.","l":["من أعطى واتقى الله يسّر الله له الخير","البخل يُبعد عن الخير","نعطي لله، لا ليمدحنا الناس"],"q":[["من ييسّر الله له طريق الخير؟",["من أعطى واتقى","من بخل","من كذّب"]],["لماذا يعطي المؤمن ماله؟",["لوجه الله","ليمدحه الناس","ليتفاخر"]]],"m":"أعطِ لله، يُيسّر الله لك كل خير.","type":"meccan"},"91":{"n":91,"name":"الشمس","t":["وَٱلشَّمۡسِ وَضُحَىٰهَا","وَٱلۡقَمَرِ إِذَا تَلَىٰهَا","وَٱلنَّهَارِ إِذَا جَلَّىٰهَا","وَٱلَّيۡلِ إِذَا يَغۡشَىٰهَا","وَٱلسَّمَآءِ وَمَا بَنَىٰهَا","وَٱلۡأَرۡضِ وَمَا طَحَىٰهَا","وَنَفۡسٖ وَمَا سَوَّىٰهَا","فَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا","قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا","وَقَدۡ خَابَ مَن دَسَّىٰهَا","كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ","إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا","فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا","فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا","وَلَا يَخَافُ عُقۡبَٰهَا"],"g":6044,"a":[["day","☀️","يُقسم الله بالشمس وضوئها في الضحى."],["night","🌙","وبالقمر إذا جاء بعدها."],["day","🌞","وبالنهار إذا أظهر الشمس."],["night","🌑","وبالليل إذا غطّاها بظلامه."],["space","🌌","وبالسماء والله الذي بناها."],["earth","🌍","وبالأرض والله الذي بسطها."],["light","🧍","وبالنفس والله الذي خلقها وسوّاها."],["light","🛤️","فعرّفها طريق الخير وطريق الشر."],["light","✨","قد فاز من طهّر نفسه بالطاعة."],["desert","😞","وقد خسر من أفسد نفسه بالذنوب."],["desert","🚫","كذّبت ثمود بسبب ظلمها."],["desert","🏃","حين أسرع أشقى رجل فيهم ليقتل الناقة."],["desert","🐪⚠️","فقال لهم رسول الله صالح: احذروا أن تؤذوا ناقة الله، واتركوها تشرب."],["storm","⚡","فكذّبوه وقتلوا الناقة، فأهلكهم الله جميعًا بذنبهم."],["light","☝️","والله لا يخاف عاقبة ما فعل."]],"i":"سورة مكية يُقسم الله فيها بالشمس والقمر والليل والنهار، ليخبرنا أن الفائز من طهّر نفسه. وفيها قصة قوم ثمود الذين قتلوا الناقة التي جعلها الله معجزة لنبيهم صالح عليه السلام، فأهلكهم الله.","l":["من طهّر نفسه بالطاعة فاز","الشمس والقمر والليل والنهار آيات من الله","عصيان الله نهايته الخسارة كما حدث لثمود"],"q":[["من هو نبي قوم ثمود؟",["صالح عليه السلام","موسى","نوح"]],["ماذا فعل قوم ثمود؟",["قتلوا الناقة","أطعموا الناقة","ركبوا الناقة"]],["من الذي فاز؟",["من طهّر نفسه","من أفسد نفسه","من نام"]]],"m":"طهّر نفسك بالطاعة لتكون من الفائزين.","type":"meccan"},"90":{"n":90,"name":"البلد","t":["لَآ أُقۡسِمُ بِهَٰذَا ٱلۡبَلَدِ","وَأَنتَ حِلُّۢ بِهَٰذَا ٱلۡبَلَدِ","وَوَالِدٖ وَمَا وَلَدَ","لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِي كَبَدٍ","أَيَحۡسَبُ أَن لَّن يَقۡدِرَ عَلَيۡهِ أَحَدٌ","يَقُولُ أَهۡلَكۡتُ مَالٗا لُّبَدًا","أَيَحۡسَبُ أَن لَّمۡ يَرَهُۥٓ أَحَدٌ","أَلَمۡ نَجۡعَل لَّهُۥ عَيۡنَيۡنِ","وَلِسَانٗا وَشَفَتَيۡنِ","وَهَدَيۡنَٰهُ ٱلنَّجۡدَيۡنِ","فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ","وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ","فَكُّ رَقَبَةٍ","أَوۡ إِطۡعَٰمٌ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ","يَتِيمٗا ذَا مَقۡرَبَةٍ","أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ","ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ","أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ","وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمۡ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ","عَلَيۡهِمۡ نَارٌ مُّؤۡصَدَةُۢ"],"g":6024,"a":[["mosque","🕋","يُقسم الله بهذا البلد الحرام مكة، وأنت يا محمد ﷺ مقيم فيه.",2],["mosque","🕋","يُقسم الله بهذا البلد الحرام مكة، وأنت يا محمد ﷺ مقيم فيه.",-1],["light","👨‍👧","ويُقسم بالوالد وما وَلد."],["desert","💪","لقد خلقنا الإنسان في تعب ومشقة."],["desert","🤨","أيظن الإنسان أنه لن يقدر عليه أحد؟"],["desert","💸","يقول متفاخرًا: أنفقت مالًا كثيرًا."],["light","👁️","أيظن أن لم يره أحد؟ الله يراه."],["light","👀","ألم نجعل له عينين يرى بهما؟"],["light","👅👄","ولسانًا وشفتين يتكلم بهما؟"],["light","🛤️","وبيّنا له طريق الخير وطريق الشر."],["mountain","🧗","فهلّا اقتحم العقبة، الطريق الصعب إلى الجنة."],["mountain","❓","وما أدراك ما العقبة؟"],["light","🔓","هي تحرير إنسان من العبودية."],["desert","🍲","أو إطعام الطعام في يوم فيه جوع."],["desert","🧒","ليتيم من الأقارب."],["desert","🍞","أو مسكين فقير جدًا."],["light","🤝","ثم يكون من المؤمنين الذين يوصي بعضهم بعضًا بالصبر والرحمة."],["garden","😊","أولئك أصحاب اليمين، أهل الجنة."],["fire","⚠️","والذين كفروا بآياتنا هم أصحاب الشمال."],["fire","🔥","عليهم نار مغلقة."]],"i":"سورة مكية يُقسم الله فيها بمكة البلد الحرام، ويذكّر الإنسان بنعمه عليه: العينين واللسان والشفتين، ويدعوه إلى الطريق الصعب الذي يوصل إلى الجنة: تحرير الناس وإطعام المحتاجين.","l":["عيوننا ولساننا نعم من الله، نستعملها في الخير","طريق الجنة يحتاج صبرًا وعملًا","إطعام اليتيم والمسكين من أعظم الأعمال","نوصي بعضنا بالصبر والرحمة"],"q":[["بماذا يُقسم الله في أول السورة؟",["بمكة البلد الحرام","بالبحر","بالقمر"]],["ما هي العقبة؟",["أعمال صالحة صعبة مثل إطعام المحتاج","جبل عالٍ","لعبة"]]],"m":"استعمل نعم الله في الخير، وكن رحيمًا بالمحتاجين.","type":"meccan"},"89":{"n":89,"name":"الفجر","t":["وَٱلۡفَجۡرِ","وَلَيَالٍ عَشۡرٖ","وَٱلشَّفۡعِ وَٱلۡوَتۡرِ","وَٱلَّيۡلِ إِذَا يَسۡرِ","هَلۡ فِي ذَٰلِكَ قَسَمٌ لِّذِي حِجۡرٍ","أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍ","إِرَمَ ذَاتِ ٱلۡعِمَادِ","ٱلَّتِي لَمۡ يُخۡلَقۡ مِثۡلُهَا فِي ٱلۡبِلَٰدِ","وَثَمُودَ ٱلَّذِينَ جَابُواْ ٱلصَّخۡرَ بِٱلۡوَادِ","وَفِرۡعَوۡنَ ذِي ٱلۡأَوۡتَادِ","ٱلَّذِينَ طَغَوۡاْ فِي ٱلۡبِلَٰدِ","فَأَكۡثَرُواْ فِيهَا ٱلۡفَسَادَ","فَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ","إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ","فَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ","وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ","كَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ","وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلٗا لَّمّٗا","وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا","كَلَّآۖ إِذَا دُكَّتِ ٱلۡأَرۡضُ دَكّٗا دَكّٗا","وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا","وَجِاْيٓءَ يَوۡمَئِذِۭ بِجَهَنَّمَۚ يَوۡمَئِذٖ يَتَذَكَّرُ ٱلۡإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ","يَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي","فَيَوۡمَئِذٖ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌ","وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌ","يَـٰٓأَيَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ","ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةٗ مَّرۡضِيَّةٗ","فَٱدۡخُلِي فِي عِبَٰدِي","وَٱدۡخُلِي جَنَّتِي"],"g":5994,"a":[["dawn","🌅","يُقسم الله بالفجر."],["night","🌙","وبالليالي العشر، وهي عشر ذي الحجة."],["light","✌️☝️","وبكل شفع وفرد (زوجي وفردي)."],["night","🌌","وبالليل إذا مضى."],["light","🧠","أليس في هذا قسم مقنع لصاحب العقل؟"],["desert","🏛️","ألم تر ماذا فعل ربك بقوم عاد، أهل إرَم أصحاب الأعمدة الطويلة، التي لم يُخلق مثلها في البلاد؟",3],["desert","🏛️","ألم تر ماذا فعل ربك بقوم عاد، أهل إرَم أصحاب الأعمدة الطويلة، التي لم يُخلق مثلها في البلاد؟",-1],["desert","🏛️","ألم تر ماذا فعل ربك بقوم عاد، أهل إرَم أصحاب الأعمدة الطويلة، التي لم يُخلق مثلها في البلاد؟",-1],["mountain","🪨🏠","وثمود الذين قطعوا الصخر في الوادي وبنوا البيوت."],["desert","👑","وفرعون صاحب الجنود والقوة."],["desert","😤","الذين ظلموا في البلاد، فأكثروا فيها الفساد.",2],["desert","😤","الذين ظلموا في البلاد، فأكثروا فيها الفساد.",-1],["storm","⚡","فأنزل عليهم ربك عذابًا شديدًا."],["light","👁️","إن ربك يراقب كل شيء."],["garden","🎁😀","الإنسان إذا أعطاه ربه نعمًا يقول: ربي أكرمني."],["desert","😟","وإذا ضيّق عليه رزقه يقول: ربي أهانني."],["desert","🧒💔","كلا، بل أنتم لا تُكرمون اليتيم."],["desert","🍲","ولا يحثّ بعضكم بعضًا على إطعام المسكين."],["desert","🍖","وتأكلون الميراث أكلًا شديدًا."],["desert","💰","وتحبون المال حبًا كثيرًا."],["earth","💥","كلا، إذا دُكّت الأرض دكًّا دكًّا."],["light","😇😇","وجاء ربك، والملائكة صفوفًا صفوفًا."],["fire","🔥","وجيء يومئذ بجهنم، يومئذ يتذكر الإنسان، ولا تنفعه الذكرى."],["desert","😢","يقول: يا ليتني قدّمت أعمالًا صالحة لحياتي الحقيقية."],["storm","⚖️","ففي ذلك اليوم لا أحد يعذّب مثل عذاب الله، ولا أحد يقيّد مثل قيده.",2],["storm","⚖️","ففي ذلك اليوم لا أحد يعذّب مثل عذاب الله، ولا أحد يقيّد مثل قيده.",-1],["garden","😌","يا أيتها النفس المطمئنة المؤمنة."],["garden","🤗","ارجعي إلى ربك راضية بما أعطاك، مرضيًّا عنكِ."],["garden","👥","فادخلي مع عبادي الصالحين."],["garden","🌳🏡","وادخلي جنتي."]],"i":"سورة مكية يُقسم الله فيها بالفجر والليالي العشر، ويحكي عن أقوام ظالمين أهلكهم: عاد وثمود وفرعون. وتعلّمنا أن نكرم اليتيم ونطعم المسكين، وتُختم بنداء جميل للنفس المطمئنة.","l":["الله أهلك الظالمين المتكبرين","النعمة والضيق اختبار من الله","نُكرم اليتيم ونطعم المسكين","النفس المطمئنة جزاؤها الجنة"],"q":[["من الأقوام الذين أهلكهم الله في السورة؟",["عاد وثمود وفرعون","أصحاب الجنة","المؤمنون"]],["كيف نعامل اليتيم؟",["نُكرمه","نتركه","نأخذ ماله"]],["أين تدخل النفس المطمئنة؟",["الجنة","النار","البحر"]]],"m":"كن رحيمًا باليتيم والمسكين، لتكون من أصحاب النفس المطمئنة.","type":"meccan"},"88":{"n":88,"name":"الغاشية","t":["هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡغَٰشِيَةِ","وُجُوهٌ يَوۡمَئِذٍ خَٰشِعَةٌ","عَامِلَةٌ نَّاصِبَةٌ","تَصۡلَىٰ نَارًا حَامِيَةٗ","تُسۡقَىٰ مِنۡ عَيۡنٍ ءَانِيَةٖ","لَّيۡسَ لَهُمۡ طَعَامٌ إِلَّا مِن ضَرِيعٖ","لَّا يُسۡمِنُ وَلَا يُغۡنِي مِن جُوعٖ","وُجُوهٌ يَوۡمَئِذٖ نَّاعِمَةٌ","لِّسَعۡيِهَا رَاضِيَةٌ","فِي جَنَّةٍ عَالِيَةٖ","لَّا تَسۡمَعُ فِيهَا لَٰغِيَةٗ","فِيهَا عَيۡنٌ جَارِيَةٌ","فِيهَا سُرُرٌ مَّرۡفُوعَةٌ","وَأَكۡوَابٌ مَّوۡضُوعَةٌ","وَنَمَارِقُ مَصۡفُوفَةٌ","وَزَرَابِيُّ مَبۡثُوثَةٌ","أَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ","وَإِلَى ٱلسَّمَآءِ كَيۡفَ رُفِعَتۡ","وَإِلَى ٱلۡجِبَالِ كَيۡفَ نُصِبَتۡ","وَإِلَى ٱلۡأَرۡضِ كَيۡفَ سُطِحَتۡ","فَذَكِّرۡ إِنَّمَآ أَنتَ مُذَكِّرٌ","لَّسۡتَ عَلَيۡهِم بِمُصَيۡطِرٍ","إِلَّا مَن تَوَلَّىٰ وَكَفَرَ","فَيُعَذِّبُهُ ٱللَّهُ ٱلۡعَذَابَ ٱلۡأَكۡبَرَ","إِنَّ إِلَيۡنَآ إِيَابَهُمۡ","ثُمَّ إِنَّ عَلَيۡنَا حِسَابَهُم"],"g":5968,"a":[["storm","❓","هل جاءك خبر يوم القيامة الذي يغطّي الناس بأهواله؟"],["storm","😞","وجوه يومئذ ذليلة، متعبة من العمل بلا فائدة.",2],["storm","😞","وجوه يومئذ ذليلة، متعبة من العمل بلا فائدة.",-1],["fire","🔥","تدخل نارًا شديدة الحرارة."],["fire","♨️","تُسقى من عين شديدة الحرارة."],["fire","🌵","ليس لهم طعام إلا شوك يابس، لا يُسمن ولا يُشبع.",2],["fire","🌵","ليس لهم طعام إلا شوك يابس، لا يُسمن ولا يُشبع.",-1],["garden","😊","ووجوه يومئذ ناعمة فرحة، راضية بعملها.",2],["garden","😊","ووجوه يومئذ ناعمة فرحة، راضية بعملها.",-1],["garden","🏞️","في جنة عالية."],["garden","🤫","لا يسمعون فيها كلامًا سيئًا."],["garden","💧","فيها عين جارية."],["garden","🛋️","فيها سُرر مرتفعة."],["garden","🥤","وأكواب موضوعة."],["garden","🛋️","ووسائد مصفوفة."],["garden","🧶","وبُسط جميلة مفروشة."],["desert","🐪","أفلا ينظرون إلى الإبل كيف خُلقت؟"],["space","🌌","وإلى السماء كيف رُفعت؟"],["mountain","⛰️","وإلى الجبال كيف نُصبت؟"],["earth","🏜️","وإلى الأرض كيف بُسطت؟"],["desert","📢","فذكّر الناس، إنما أنت مذكّر."],["desert","🙂","لستَ عليهم بمسيطر تجبرهم على الإيمان."],["fire","⚠️","لكن من أعرض وكفر، فسيعذّبه الله العذاب الأكبر.",2],["fire","⚠️","لكن من أعرض وكفر، فسيعذّبه الله العذاب الأكبر.",-1],["light","☝️","إن رجوعهم إلينا، ثم إن علينا حسابهم.",2],["light","☝️","إن رجوعهم إلينا، ثم إن علينا حسابهم.",-1]],"i":"سورة مكية كان النبي ﷺ يقرؤها في صلاة الجمعة. تحكي عن يوم القيامة وحال أهل النار وأهل الجنة، ثم تدعونا للتفكّر في الإبل والسماء والجبال والأرض.","l":["نتفكّر في خلق الله: الإبل والسماء والجبال والأرض","في الجنة نعيم لا ينتهي","كلنا سنرجع إلى الله"],"q":[["إلى ماذا أمرنا الله أن ننظر ونتفكّر؟",["الإبل والسماء والجبال والأرض","الهاتف","التلفاز"]],["ماذا في الجنة؟",["عين جارية وسرر مرفوعة","شوك","نار"]]],"m":"تفكّر في خلق الله من حولك، تعرف عظمته.","type":"meccan"},"87":{"n":87,"name":"الأعلى","t":["سَبِّحِ ٱسۡمَ رَبِّكَ ٱلۡأَعۡلَى","ٱلَّذِي خَلَقَ فَسَوَّىٰ","وَٱلَّذِي قَدَّرَ فَهَدَىٰ","وَٱلَّذِيٓ أَخۡرَجَ ٱلۡمَرۡعَىٰ","فَجَعَلَهُۥ غُثَآءً أَحۡوَىٰ","سَنُقۡرِئُكَ فَلَا تَنسَىٰٓ","إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ وَمَا يَخۡفَىٰ","وَنُيَسِّرُكَ لِلۡيُسۡرَىٰ","فَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ","سَيَذَّكَّرُ مَن يَخۡشَىٰ","وَيَتَجَنَّبُهَا ٱلۡأَشۡقَى","ٱلَّذِي يَصۡلَى ٱلنَّارَ ٱلۡكُبۡرَىٰ","ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ","قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ","وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ","بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا","وَٱلۡأٓخِرَةُ خَيۡرٌ وَأَبۡقَىٰٓ","إِنَّ هَٰذَا لَفِي ٱلصُّحُفِ ٱلۡأُولَىٰ","صُحُفِ إِبۡرَٰهِيمَ وَمُوسَىٰ"],"g":5949,"a":[["sky","🤲✨","سبّح اسم ربك الأعلى، ونزّهه عن كل نقص."],["light","🧍","الذي خلق كل شيء فسوّاه وأحسن خلقه."],["light","🧭","والذي قدّر لكل شيء ما يناسبه، وهدى كل مخلوق لما ينفعه."],["garden","🌿","والذي أخرج العشب الأخضر للحيوانات."],["desert","🍂","ثم جعله يابسًا أسود."],["light","📖🧠","سنُقرئك القرآن يا محمد ﷺ فلا تنساه، إلا ما شاء الله، إنه يعلم الظاهر والخفي.",2],["light","📖🧠","سنُقرئك القرآن يا محمد ﷺ فلا تنساه، إلا ما شاء الله، إنه يعلم الظاهر والخفي.",-1],["light","🛤️","ونُيسّرك للطريق السهل."],["desert","📢","فذكّر الناس بالقرآن ما دامت التذكرة تنفع."],["light","🙂","سيتذكر ويتّعظ من يخاف الله."],["fire","🔥","ويبتعد عنها الشقي، الذي يدخل النار الكبرى، لا يموت فيها ولا يحيا حياة طيبة.",3],["fire","🔥","ويبتعد عنها الشقي، الذي يدخل النار الكبرى، لا يموت فيها ولا يحيا حياة طيبة.",-1],["fire","🔥","ويبتعد عنها الشقي، الذي يدخل النار الكبرى، لا يموت فيها ولا يحيا حياة طيبة.",-1],["mosque","✨","قد فاز من طهّر نفسه من الذنوب."],["mosque","🕌🙏","وذكر اسم ربه فصلّى."],["desert","🏃💰","لكنكم تفضّلون الحياة الدنيا."],["garden","🌳","والآخرة خير وأبقى."],["light","📜","هذا الكلام مكتوب أيضًا في الصحف الأولى: صحف إبراهيم وموسى.",2],["light","📜","هذا الكلام مكتوب أيضًا في الصحف الأولى: صحف إبراهيم وموسى.",-1]],"i":"سورة مكية كان النبي ﷺ يحبها ويقرؤها في صلاة الجمعة والعيد. تأمرنا أن نسبّح الله الأعلى، وتخبرنا أن الفلاح لمن تطهّر وذكر الله وصلّى.","l":["نسبّح الله ونقول في السجود: سبحان ربي الأعلى","الفلاح لمن طهّر قلبه وذكر الله وصلّى","الآخرة خير وأبقى من الدنيا"],"q":[["ماذا نقول في السجود؟",["سبحان ربي الأعلى","مرحبًا","شكرًا"]],["من الذي فاز؟",["من طهّر نفسه وصلّى","من لعب كثيرًا","من نام"]],["أيهما أبقى؟",["الآخرة","الدنيا","الألعاب"]]],"m":"سبّح ربك الأعلى، وطهّر قلبك، وحافظ على صلاتك.","type":"meccan"},"86":{"n":86,"name":"الطارق","t":["وَٱلسَّمَآءِ وَٱلطَّارِقِ","وَمَآ أَدۡرَىٰكَ مَا ٱلطَّارِقُ","ٱلنَّجۡمُ ٱلثَّاقِبُ","إِن كُلُّ نَفۡسٖ لَّمَّا عَلَيۡهَا حَافِظٌ","فَلۡيَنظُرِ ٱلۡإِنسَٰنُ مِمَّ خُلِقَ","خُلِقَ مِن مَّآءٖ دَافِقٖ","يَخۡرُجُ مِنۢ بَيۡنِ ٱلصُّلۡبِ وَٱلتَّرَآئِبِ","إِنَّهُۥ عَلَىٰ رَجۡعِهِۦ لَقَادِرٌ","يَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ","فَمَا لَهُۥ مِن قُوَّةٖ وَلَا نَاصِرٖ","وَٱلسَّمَآءِ ذَاتِ ٱلرَّجۡعِ","وَٱلۡأَرۡضِ ذَاتِ ٱلصَّدۡعِ","إِنَّهُۥ لَقَوۡلٌ فَصۡلٌ","وَمَا هُوَ بِٱلۡهَزۡلِ","إِنَّهُمۡ يَكِيدُونَ كَيۡدٗا","وَأَكِيدُ كَيۡدٗا","فَمَهِّلِ ٱلۡكَٰفِرِينَ أَمۡهِلۡهُمۡ رُوَيۡدَۢا"],"g":5932,"a":[["night","🌌✨","يُقسم الله بالسماء وبالنجم الذي يظهر في الليل."],["night","❓","وما أدراك ما الطارق؟"],["night","⭐","هو النجم المضيء الذي يثقب الظلام بنوره."],["light","😇🛡️","ما من إنسان إلا وعليه ملك يحفظه."],["light","🤔","فلينظر الإنسان: من أي شيء خُلق؟"],["light","💧","خُلق من ماء صغير، بقدرة الله.",2],["light","💧","خُلق من ماء صغير، بقدرة الله.",-1],["light","🔄","إن الله قادر على إعادته حيًا بعد موته."],["light","🔍","يوم تُكشف الأسرار."],["light","🚫","فلا يكون للإنسان قوة ولا ناصر."],["rain","🌧️","يُقسم الله بالسماء ذات المطر الذي يرجع."],["earth","🌱","وبالأرض التي تنشقّ بالنبات."],["light","📖","إن القرآن قول فصل بين الحق والباطل."],["light","🚫","وما هو بالهزل واللعب."],["desert","🧩","إن الكفار يدبّرون ضد الحق، والله يدبّر ويُبطل كيدهم.",2],["desert","🧩","إن الكفار يدبّرون ضد الحق، والله يدبّر ويُبطل كيدهم.",-1],["desert","⏳","فأمهِل الكافرين قليلًا، وسيرون عاقبتهم."]],"i":"سورة مكية يُقسم الله فيها بالسماء والنجم المضيء، ليخبرنا أن على كل إنسان ملكًا يحفظه، ويذكّرنا بقدرته على خلقنا وإعادتنا.","l":["الله جعل لكل إنسان ملكًا يحفظه","الله الذي خلقنا قادر على أن يعيدنا","القرآن كلام جادّ يفرّق بين الحق والباطل"],"q":[["ما هو الطارق؟",["النجم المضيء","الطائرة","الطائر"]],["من يحفظ الإنسان بأمر الله؟",["ملك حافظ","صديقه","لا أحد"]]],"m":"الله يحفظك دائمًا، فاحفظ أوامره.","type":"meccan"},"85":{"n":85,"name":"البروج","t":["وَٱلسَّمَآءِ ذَاتِ ٱلۡبُرُوجِ","وَٱلۡيَوۡمِ ٱلۡمَوۡعُودِ","وَشَاهِدٖ وَمَشۡهُودٖ","قُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ","ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ","إِذۡ هُمۡ عَلَيۡهَا قُعُودٌ","وَهُمۡ عَلَىٰ مَا يَفۡعَلُونَ بِٱلۡمُؤۡمِنِينَ شُهُودٌ","وَمَا نَقَمُواْ مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ","ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ","إِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِيقِ","إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ جَنَّـٰتٌ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡكَبِيرُ","إِنَّ بَطۡشَ رَبِّكَ لَشَدِيدٌ","إِنَّهُۥ هُوَ يُبۡدِئُ وَيُعِيدُ","وَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ","ذُو ٱلۡعَرۡشِ ٱلۡمَجِيدُ","فَعَّالٌ لِّمَا يُرِيدُ","هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡجُنُودِ","فِرۡعَوۡنَ وَثَمُودَ","بَلِ ٱلَّذِينَ كَفَرُواْ فِي تَكۡذِيبٖ","وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطُۢ","بَلۡ هُوَ قُرۡءَانٌ مَّجِيدٌ","فِي لَوۡحٖ مَّحۡفُوظِۭ"],"g":5910,"a":[["night","✨🌌","يُقسم الله بالسماء ذات النجوم العظيمة."],["sky","⏳","وبيوم القيامة الموعود."],["sky","👀","وبكل شاهد، وكل ما يُشهد عليه يوم القيامة."],["fire","🔥🕳️","لُعن أصحاب الأخدود، الحفرة العظيمة التي أشعلوا فيها النار.",2],["fire","🔥🕳️","لُعن أصحاب الأخدود، الحفرة العظيمة التي أشعلوا فيها النار.",-1],["fire","🪑👀","إذ هم جالسون حولها، يشاهدون ما يفعلون بالمؤمنين.",2],["fire","🪑👀","إذ هم جالسون حولها، يشاهدون ما يفعلون بالمؤمنين.",-1],["light","☝️💖","وما عاقبوهم إلا لأنهم آمنوا بالله العزيز الحميد."],["space","👑","الذي له ملك السماوات والأرض، والله شاهد على كل شيء."],["fire","⚠️","إن الذين آذوا المؤمنين ثم لم يتوبوا، فلهم عذاب جهنم."],["garden","🌳🏆","إن الذين آمنوا وعملوا الصالحات لهم جنات تجري تحتها الأنهار، ذلك الفوز الكبير."],["storm","💪","إن عقاب ربك للظالمين شديد."],["light","🌱","هو الذي يبدأ الخلق، ثم يعيده بعد الموت."],["light","💖","وهو الغفور لمن تاب، الودود الذي يحب عباده المؤمنين."],["space","👑","صاحب العرش العظيم."],["light","✨","يفعل ما يريد، لا يمنعه أحد."],["desert","⚔️","هل جاءك خبر الجنود الكفار: فرعون وقوم ثمود؟",2],["desert","⚔️","هل جاءك خبر الجنود الكفار: فرعون وقوم ثمود؟",-1],["desert","🚫","بل الكفار في تكذيب."],["light","👁️","والله محيط بهم، لا يفوتونه."],["light","📖🛡️","بل هو قرآن مجيد، محفوظ في اللوح المحفوظ.",2],["light","📖🛡️","بل هو قرآن مجيد، محفوظ في اللوح المحفوظ.",-1]],"i":"سورة مكية فيها قصة أصحاب الأخدود: ملك ظالم حفر حفرة كبيرة وأشعل فيها النار، ليُعذّب المؤمنين الذين آمنوا بالله، فصبروا وثبتوا على إيمانهم. فلهم الجنة، والله ينتقم من الظالمين.","l":["نثبت على الإيمان مهما حدث","الله يرى الظالم وسيعاقبه","الله الودود يحب المؤمنين","القرآن محفوظ"],"q":[["ماذا فعل أصحاب الأخدود؟",["عذّبوا المؤمنين بالنار","بنوا مسجدًا","زرعوا"]],["لماذا عذّبوا المؤمنين؟",["لأنهم آمنوا بالله","لأنهم سرقوا","لأنهم كذبوا"]],["ما معنى الودود؟",["الذي يحب عباده المؤمنين","الغاضب","البعيد"]]],"m":"اثبت على إيمانك، فالله معك ويحبك.","type":"meccan"},"84":{"n":84,"name":"الإنشقاق","t":["إِذَا ٱلسَّمَآءُ ٱنشَقَّتۡ","وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ","وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ","وَأَلۡقَتۡ مَا فِيهَا وَتَخَلَّتۡ","وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ","يَـٰٓأَيُّهَا ٱلۡإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحٗا فَمُلَٰقِيهِ","فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ","فَسَوۡفَ يُحَاسَبُ حِسَابٗا يَسِيرٗا","وَيَنقَلِبُ إِلَىٰٓ أَهۡلِهِۦ مَسۡرُورٗا","وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ","فَسَوۡفَ يَدۡعُواْ ثُبُورٗا","وَيَصۡلَىٰ سَعِيرًا","إِنَّهُۥ كَانَ فِيٓ أَهۡلِهِۦ مَسۡرُورًا","إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ","بَلَىٰٓۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرٗا","فَلَآ أُقۡسِمُ بِٱلشَّفَقِ","وَٱلَّيۡلِ وَمَا وَسَقَ","وَٱلۡقَمَرِ إِذَا ٱتَّسَقَ","لَتَرۡكَبُنَّ طَبَقًا عَن طَبَقٖ","فَمَا لَهُمۡ لَا يُؤۡمِنُونَ","وَإِذَا قُرِئَ عَلَيۡهِمُ ٱلۡقُرۡءَانُ لَا يَسۡجُدُونَۤ۩","بَلِ ٱلَّذِينَ كَفَرُواْ يُكَذِّبُونَ","وَٱللَّهُ أَعۡلَمُ بِمَا يُوعُونَ","فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ","إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونِۭ"],"g":5885,"a":[["space","💥","إذا السماء انشقّت، وسمعت أمر ربها وأطاعت، وحُقّ لها أن تطيع.",2],["space","💥","إذا السماء انشقّت، وسمعت أمر ربها وأطاعت، وحُقّ لها أن تطيع.",-1],["earth","🌍","وإذا الأرض مُدّت، وأخرجت ما في داخلها، وسمعت أمر ربها وأطاعت.",3],["earth","🌍","وإذا الأرض مُدّت، وأخرجت ما في داخلها، وسمعت أمر ربها وأطاعت.",-1],["earth","🌍","وإذا الأرض مُدّت، وأخرجت ما في داخلها، وسمعت أمر ربها وأطاعت.",-1],["desert","🚶🛤️","يا أيها الإنسان، إنك تعمل وتسعى في حياتك حتى تلقى ربك فيجازيك."],["garden","📗😊","فأما من أُعطي كتابه بيمينه، فحسابه سهل، ويرجع إلى أهله فرحًا.",3],["garden","📗😊","فأما من أُعطي كتابه بيمينه، فحسابه سهل، ويرجع إلى أهله فرحًا.",-1],["garden","📗😊","فأما من أُعطي كتابه بيمينه، فحسابه سهل، ويرجع إلى أهله فرحًا.",-1],["fire","📕😢","وأما من أُعطي كتابه من وراء ظهره، فسيدعو على نفسه بالهلاك، ويدخل النار.",3],["fire","📕😢","وأما من أُعطي كتابه من وراء ظهره، فسيدعو على نفسه بالهلاك، ويدخل النار.",-1],["fire","📕😢","وأما من أُعطي كتابه من وراء ظهره، فسيدعو على نفسه بالهلاك، ويدخل النار.",-1],["desert","😆🏠","لأنه كان في الدنيا فرحًا مغرورًا بين أهله."],["desert","🙄","ظنّ أنه لن يرجع إلى ربه."],["light","👁️","بلى، إن ربه كان يراه."],["dawn","🌇","يُقسم الله بحُمرة السماء بعد غروب الشمس."],["night","🌙","وبالليل وما جمع فيه."],["night","🌕","وبالقمر إذا اكتمل بدرًا."],["sky","🪜","لتمرّنّ بأحوال كثيرة، حالًا بعد حال."],["desert","❓","فما لهم لا يؤمنون؟"],["mosque","📖🙇","وإذا قُرئ عليهم القرآن لا يسجدون."],["desert","🚫","بل الكفار يكذّبون."],["light","👁️","والله أعلم بما في قلوبهم."],["fire","⚠️","فأخبرهم بعذاب أليم."],["garden","🎁","إلا الذين آمنوا وعملوا الصالحات، فلهم أجر لا ينقطع."]],"i":"سورة مكية تصف يوم القيامة حين تنشقّ السماء وتُمدّ الأرض، وتخبرنا أن كل إنسان سيأخذ كتاب أعماله: المؤمن بيمينه فيفرح، والكافر من وراء ظهره فيحزن.","l":["كل إنسان سيلقى ربه ويرى عمله","المؤمن يأخذ كتابه بيمينه ويفرح","الله يرانا دائمًا"],"q":[["كيف يأخذ المؤمن كتابه؟",["بيمينه","بشماله","لا يأخذه"]],["ماذا يفعل المؤمن بعد حسابه السهل؟",["يرجع إلى أهله فرحًا","يبكي","يهرب"]]],"m":"اعمل الخير لتأخذ كتابك بيمينك وتفرح.","type":"meccan"},"83":{"n":83,"name":"المطففين","t":["وَيۡلٌ لِّلۡمُطَفِّفِينَ","ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ","وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ","أَلَا يَظُنُّ أُوْلَـٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ","لِيَوۡمٍ عَظِيمٖ","يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ","كَلَّآ إِنَّ كِتَٰبَ ٱلۡفُجَّارِ لَفِي سِجِّينٖ","وَمَآ أَدۡرَىٰكَ مَا سِجِّينٌ","كِتَٰبٌ مَّرۡقُومٌ","وَيۡلٌ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","ٱلَّذِينَ يُكَذِّبُونَ بِيَوۡمِ ٱلدِّينِ","وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعۡتَدٍ أَثِيمٍ","إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ","كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ","كَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ يَوۡمَئِذٖ لَّمَحۡجُوبُونَ","ثُمَّ إِنَّهُمۡ لَصَالُواْ ٱلۡجَحِيمِ","ثُمَّ يُقَالُ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ","كَلَّآ إِنَّ كِتَٰبَ ٱلۡأَبۡرَارِ لَفِي عِلِّيِّينَ","وَمَآ أَدۡرَىٰكَ مَا عِلِّيُّونَ","كِتَٰبٌ مَّرۡقُومٌ","يَشۡهَدُهُ ٱلۡمُقَرَّبُونَ","إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٍ","عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ","تَعۡرِفُ فِي وُجُوهِهِمۡ نَضۡرَةَ ٱلنَّعِيمِ","يُسۡقَوۡنَ مِن رَّحِيقٖ مَّخۡتُومٍ","خِتَٰمُهُۥ مِسۡكٌۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ","وَمِزَاجُهُۥ مِن تَسۡنِيمٍ","عَيۡنٗا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ","إِنَّ ٱلَّذِينَ أَجۡرَمُواْ كَانُواْ مِنَ ٱلَّذِينَ ءَامَنُواْ يَضۡحَكُونَ","وَإِذَا مَرُّواْ بِهِمۡ يَتَغَامَزُونَ","وَإِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمُ ٱنقَلَبُواْ فَكِهِينَ","وَإِذَا رَأَوۡهُمۡ قَالُوٓاْ إِنَّ هَـٰٓؤُلَآءِ لَضَآلُّونَ","وَمَآ أُرۡسِلُواْ عَلَيۡهِمۡ حَٰفِظِينَ","فَٱلۡيَوۡمَ ٱلَّذِينَ ءَامَنُواْ مِنَ ٱلۡكُفَّارِ يَضۡحَكُونَ","عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ","هَلۡ ثُوِّبَ ٱلۡكُفَّارُ مَا كَانُواْ يَفۡعَلُونَ"],"g":5849,"a":[["desert","⚖️⚠️","الويل للذين يغشّون في الكيل والميزان."],["desert","⚖️➕","الذين إذا اشتروا من الناس أخذوا حقهم كاملًا."],["desert","⚖️➖","وإذا باعوا للناس أنقصوا لهم."],["sky","❓👥","ألا يظن هؤلاء أنهم سيُبعثون ليوم عظيم، يوم يقف الناس أمام ربّ العالمين؟",3],["sky","❓👥","ألا يظن هؤلاء أنهم سيُبعثون ليوم عظيم، يوم يقف الناس أمام ربّ العالمين؟",-1],["sky","❓👥","ألا يظن هؤلاء أنهم سيُبعثون ليوم عظيم، يوم يقف الناس أمام ربّ العالمين؟",-1],["night","📒⬇️","إن كتاب أعمال الفجّار في سِجّين، مكان في الأرض السفلى."],["night","📒","وما أدراك ما سجّين؟ كتاب مكتوب لا يُزاد فيه ولا يُنقص.",2],["night","📒","وما أدراك ما سجّين؟ كتاب مكتوب لا يُزاد فيه ولا يُنقص.",-1],["fire","⚠️","ويل يومئذ للمكذبين الذين يكذّبون بيوم الدين، وما يكذّب به إلا كل معتدٍ كثير الذنوب.",3],["fire","⚠️","ويل يومئذ للمكذبين الذين يكذّبون بيوم الدين، وما يكذّب به إلا كل معتدٍ كثير الذنوب.",-1],["fire","⚠️","ويل يومئذ للمكذبين الذين يكذّبون بيوم الدين، وما يكذّب به إلا كل معتدٍ كثير الذنوب.",-1],["desert","🙄📖","إذا قُرئت عليه آيات الله قال: هذه حكايات القدماء."],["desert","🖤","كلا، بل غطّت ذنوبهم على قلوبهم."],["fire","🚫","إنهم يوم القيامة محجوبون عن رؤية ربهم."],["fire","🔥","ثم إنهم داخلو الجحيم، ويُقال لهم: هذا الذي كنتم تكذّبون به.",2],["fire","🔥","ثم إنهم داخلو الجحيم، ويُقال لهم: هذا الذي كنتم تكذّبون به.",-1],["light","📒⬆️","إن كتاب أعمال الأبرار في علّيّين، مكان عالٍ، كتاب مكتوب تحضره الملائكة المقرّبون.",4],["light","📒⬆️","إن كتاب أعمال الأبرار في علّيّين، مكان عالٍ، كتاب مكتوب تحضره الملائكة المقرّبون.",-1],["light","📒⬆️","إن كتاب أعمال الأبرار في علّيّين، مكان عالٍ، كتاب مكتوب تحضره الملائكة المقرّبون.",-1],["light","📒⬆️","إن كتاب أعمال الأبرار في علّيّين، مكان عالٍ، كتاب مكتوب تحضره الملائكة المقرّبون.",-1],["garden","😊","إن الأبرار في نعيم."],["garden","🛋️👀","على الأسرّة الجميلة ينظرون."],["garden","✨😊","ترى في وجوههم بهجة النعيم."],["garden","🥤","يشربون من شراب صافٍ مختوم بالمسك، وفي ذلك فليتسابق المتسابقون.",2],["garden","🥤","يشربون من شراب صافٍ مختوم بالمسك، وفي ذلك فليتسابق المتسابقون.",-1],["garden","💧","يُمزج بماء من عين اسمها تسنيم، يشرب منها المقرّبون.",2],["garden","💧","يُمزج بماء من عين اسمها تسنيم، يشرب منها المقرّبون.",-1],["desert","😆👉","كان الكفار في الدنيا يضحكون من المؤمنين، وإذا مرّوا بهم أشار بعضهم لبعض سخرية.",2],["desert","😆👉","كان الكفار في الدنيا يضحكون من المؤمنين، وإذا مرّوا بهم أشار بعضهم لبعض سخرية.",-1],["desert","🏠😆","وإذا رجعوا إلى أهلهم رجعوا فرحين بما فعلوا."],["desert","👉","وإذا رأوا المؤمنين قالوا: هؤلاء ضالّون."],["desert","🚫","وما أُرسلوا ليراقبوا المؤمنين."],["garden","😊","فاليوم، يوم القيامة، المؤمنون يضحكون من الكفار."],["garden","🛋️👀","على الأسرّة ينظرون."],["light","⚖️","هل جُوزي الكفار بما كانوا يفعلون؟ نعم."]],"i":"نزلت في أول الهجرة إلى المدينة، وكان بعض التجار يغشّون في الكيل والميزان: يأخذون حقهم كاملًا، ويُنقصون حق الناس. فحذّرهم الله من الغش، وذكّرهم بيوم الحساب.","l":["الغشّ في البيع والشراء حرام","نعطي الناس حقهم كاملًا كما نحب أن نأخذ حقنا","الذنوب تغطي القلب، فلنكثر من التوبة","لا نسخر من الناس"],"q":[["ماذا كان المطفّفون يفعلون؟",["يغشّون في الميزان","يتصدّقون","يصلّون"]],["أين كتاب أعمال الأبرار؟",["في علّيّين","في سجّين","في البحر"]],["هل يجوز أن نسخر من الآخرين؟",["لا","نعم","أحيانًا"]]],"m":"كن أمينًا في كل شيء، وأعطِ الناس حقهم كاملًا.","type":"meccan"},"82":{"n":82,"name":"الإنفطار","t":["إِذَا ٱلسَّمَآءُ ٱنفَطَرَتۡ","وَإِذَا ٱلۡكَوَاكِبُ ٱنتَثَرَتۡ","وَإِذَا ٱلۡبِحَارُ فُجِّرَتۡ","وَإِذَا ٱلۡقُبُورُ بُعۡثِرَتۡ","عَلِمَتۡ نَفۡسٌ مَّا قَدَّمَتۡ وَأَخَّرَتۡ","يَـٰٓأَيُّهَا ٱلۡإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِيمِ","ٱلَّذِي خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ","فِيٓ أَيِّ صُورَةٖ مَّا شَآءَ رَكَّبَكَ","كَلَّا بَلۡ تُكَذِّبُونَ بِٱلدِّينِ","وَإِنَّ عَلَيۡكُمۡ لَحَٰفِظِينَ","كِرَامٗا كَٰتِبِينَ","يَعۡلَمُونَ مَا تَفۡعَلُونَ","إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ","وَإِنَّ ٱلۡفُجَّارَ لَفِي جَحِيمٖ","يَصۡلَوۡنَهَا يَوۡمَ ٱلدِّينِ","وَمَا هُمۡ عَنۡهَا بِغَآئِبِينَ","وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ","ثُمَّ مَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ","يَوۡمَ لَا تَمۡلِكُ نَفۡسٌ لِّنَفۡسٖ شَيۡـٔٗاۖ وَٱلۡأَمۡرُ يَوۡمَئِذٖ لِّلَّهِ"],"g":5830,"a":[["space","💥","إذا السماء انشقّت."],["space","⭐💫","وإذا النجوم تساقطت وتفرّقت."],["sea","🌊","وإذا البحار فُجّرت واختلطت."],["desert","🪦","وإذا القبور فُتحت وخرج من فيها."],["light","📋","عندها تعلم كل نفس ما قدّمت وما أخّرت."],["light","❓💖","يا أيها الإنسان، ما الذي غرّك بربك الكريم حتى عصيته؟"],["light","🧍✨","الذي خلقك، وجعل جسمك مستويًا معتدلًا."],["light","🎨","وصوّرك في الصورة التي شاءها."],["desert","🚫","ولكن الكفار يكذّبون بيوم الحساب."],["light","😇✍️","وعليكم ملائكة حافظون، كرام كاتبون، يعلمون ما تفعلون.",3],["light","😇✍️","وعليكم ملائكة حافظون، كرام كاتبون، يعلمون ما تفعلون.",-1],["light","😇✍️","وعليكم ملائكة حافظون، كرام كاتبون، يعلمون ما تفعلون.",-1],["garden","🌳😊","إن الأبرار في نعيم الجنة."],["fire","🔥","وإن الفجّار في جهنم."],["fire","🔥","يدخلونها يوم الدين، ولا يغيبون عنها.",2],["fire","🔥","يدخلونها يوم الدين، ولا يغيبون عنها.",-1],["sky","❓","وما أدراك ما يوم الدين؟ يوم عظيم.",2],["sky","❓","وما أدراك ما يوم الدين؟ يوم عظيم.",-1],["light","☝️","يوم لا يملك أحد لأحد شيئًا، والأمر كله يومئذ لله."]],"i":"سورة مكية تذكّرنا بيوم القيامة حين تنشقّ السماء، وتذكّر الإنسان بكرم الله الذي خلقه في أحسن صورة، وأن معنا ملائكة يكتبون كل أعمالنا.","l":["الله كريم، خلقنا في أحسن صورة","معنا ملائكة يكتبون أعمالنا","يوم القيامة الأمر كله لله"],"q":[["من يكتب أعمالنا؟",["الملائكة الكرام","أصدقاؤنا","لا أحد"]],["أين يكون الأبرار؟",["في نعيم الجنة","في النار","في البحر"]]],"m":"الملائكة تكتب كل ما نفعل، فلنفعل ما يحبه الله.","type":"meccan"},"81":{"n":81,"name":"التكوير","t":["إِذَا ٱلشَّمۡسُ كُوِّرَتۡ","وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتۡ","وَإِذَا ٱلۡجِبَالُ سُيِّرَتۡ","وَإِذَا ٱلۡعِشَارُ عُطِّلَتۡ","وَإِذَا ٱلۡوُحُوشُ حُشِرَتۡ","وَإِذَا ٱلۡبِحَارُ سُجِّرَتۡ","وَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ","وَإِذَا ٱلۡمَوۡءُۥدَةُ سُئِلَتۡ","بِأَيِّ ذَنۢبٖ قُتِلَتۡ","وَإِذَا ٱلصُّحُفُ نُشِرَتۡ","وَإِذَا ٱلسَّمَآءُ كُشِطَتۡ","وَإِذَا ٱلۡجَحِيمُ سُعِّرَتۡ","وَإِذَا ٱلۡجَنَّةُ أُزۡلِفَتۡ","عَلِمَتۡ نَفۡسٌ مَّآ أَحۡضَرَتۡ","فَلَآ أُقۡسِمُ بِٱلۡخُنَّسِ","ٱلۡجَوَارِ ٱلۡكُنَّسِ","وَٱلَّيۡلِ إِذَا عَسۡعَسَ","وَٱلصُّبۡحِ إِذَا تَنَفَّسَ","إِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ","ذِي قُوَّةٍ عِندَ ذِي ٱلۡعَرۡشِ مَكِينٖ","مُّطَاعٖ ثَمَّ أَمِينٖ","وَمَا صَاحِبُكُم بِمَجۡنُونٖ","وَلَقَدۡ رَءَاهُ بِٱلۡأُفُقِ ٱلۡمُبِينِ","وَمَا هُوَ عَلَى ٱلۡغَيۡبِ بِضَنِينٖ","وَمَا هُوَ بِقَوۡلِ شَيۡطَٰنٖ رَّجِيمٖ","فَأَيۡنَ تَذۡهَبُونَ","إِنۡ هُوَ إِلَّا ذِكۡرٌ لِّلۡعَٰلَمِينَ","لِمَن شَآءَ مِنكُمۡ أَن يَسۡتَقِيمَ","وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ"],"g":5801,"a":[["space","☀️🌀","إذا الشمس لُفّت وذهب ضوؤها."],["space","⭐💫","وإذا النجوم تساقطت."],["mountain","⛰️💨","وإذا الجبال سُيّرت من أماكنها."],["desert","🐪","وإذا النوق الحوامل تُركت، فلا يهتم بها أحد."],["garden","🦁🐘🦒","وإذا الوحوش جُمعت."],["sea","🌊🔥","وإذا البحار أُشعلت نارًا."],["light","👥","وإذا جُمع كل إنسان مع أمثاله."],["light","❓👧","ويُسأل عن البنت المظلومة التي قتلها أهلها في الجاهلية: لماذا قُتلت؟ وهي بلا ذنب.",2],["light","❓👧","ويُسأل عن البنت المظلومة التي قتلها أهلها في الجاهلية: لماذا قُتلت؟ وهي بلا ذنب.",-1],["light","📒","وإذا صحف الأعمال فُتحت."],["space","🌌","وإذا السماء كُشفت وأُزيلت."],["fire","🔥","وإذا جهنم أُشعلت."],["garden","🌳✨","وإذا الجنة قُرّبت للمتقين."],["light","📋","عندها تعلم كل نفس ما قدّمت من عمل."],["night","✨","يُقسم الله بالنجوم التي تختفي في النهار وتجري في الليل.",2],["night","✨","يُقسم الله بالنجوم التي تختفي في النهار وتجري في الليل.",-1],["night","🌙","وبالليل إذا أقبل بظلامه."],["dawn","🌅","وبالصبح إذا أضاء."],["light","😇📖","إن القرآن كلام الله، نزل به جبريل: رسول كريم، قوي، مكانته عالية عند الله، أمين.",3],["light","😇📖","إن القرآن كلام الله، نزل به جبريل: رسول كريم، قوي، مكانته عالية عند الله، أمين.",-1],["light","😇📖","إن القرآن كلام الله، نزل به جبريل: رسول كريم، قوي، مكانته عالية عند الله، أمين.",-1],["desert","🙂","وما صاحبكم محمد ﷺ بمجنون."],["dawn","😇","ولقد رأى النبي ﷺ جبريل في الأفق الواضح."],["light","🤲","وما هو ببخيل في تبليغ الوحي."],["light","🚫😈","وما القرآن بكلام شيطان."],["desert","🛤️❓","فأين تذهبون عن هذا الحق؟"],["light","📖🌍","ما هو إلا تذكير للعالمين."],["light","🛤️","لمن شاء منكم أن يستقيم على الحق."],["light","☝️","ولا تشاؤون شيئًا إلا أن يشاء الله ربّ العالمين."]],"i":"سورة مكية تصف أحداث يوم القيامة العظيمة: الشمس تُلفّ، والنجوم تتساقط، والجبال تتحرك. ثم تخبرنا أن القرآن نزل به جبريل عليه السلام، وأنه تذكير للعالمين.","l":["يوم القيامة يوم عظيم تتغير فيه الدنيا كلها","كل أعمالنا مكتوبة وسنراها","القرآن كلام الله نزل به جبريل","الإسلام أكرم البنات وحرّم ظلمهن"],"q":[["من الذي نزل بالقرآن على النبي ﷺ؟",["جبريل عليه السلام","إنسان","طائر"]],["ماذا يحدث للشمس يوم القيامة؟",["تُلفّ ويذهب ضوؤها","تصير أكبر","تبقى كما هي"]],["القرآن تذكير لمن؟",["للعالمين","للعرب فقط","للكبار فقط"]]],"m":"القرآن تذكير لنا جميعًا، فلنستقم على طريق الحق.","type":"meccan"},"80":{"n":80,"name":"عبس","t":["عَبَسَ وَتَوَلَّىٰٓ","أَن جَآءَهُ ٱلۡأَعۡمَىٰ","وَمَا يُدۡرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ","أَوۡ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكۡرَىٰٓ","أَمَّا مَنِ ٱسۡتَغۡنَىٰ","فَأَنتَ لَهُۥ تَصَدَّىٰ","وَمَا عَلَيۡكَ أَلَّا يَزَّكَّىٰ","وَأَمَّا مَن جَآءَكَ يَسۡعَىٰ","وَهُوَ يَخۡشَىٰ","فَأَنتَ عَنۡهُ تَلَهَّىٰ","كَلَّآ إِنَّهَا تَذۡكِرَةٌ","فَمَن شَآءَ ذَكَرَهُۥ","فِي صُحُفٖ مُّكَرَّمَةٖ","مَّرۡفُوعَةٖ مُّطَهَّرَةِۭ","بِأَيۡدِي سَفَرَةٖ","كِرَامِۭ بَرَرَةٖ","قُتِلَ ٱلۡإِنسَٰنُ مَآ أَكۡفَرَهُۥ","مِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ","مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ","ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ","ثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ","ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ","كَلَّا لَمَّا يَقۡضِ مَآ أَمَرَهُۥ","فَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ","أَنَّا صَبَبۡنَا ٱلۡمَآءَ صَبّٗا","ثُمَّ شَقَقۡنَا ٱلۡأَرۡضَ شَقّٗا","فَأَنۢبَتۡنَا فِيهَا حَبّٗا","وَعِنَبٗا وَقَضۡبٗا","وَزَيۡتُونٗا وَنَخۡلٗا","وَحَدَآئِقَ غُلۡبٗا","وَفَٰكِهَةٗ وَأَبّٗا","مَّتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ","فَإِذَا جَآءَتِ ٱلصَّآخَّةُ","يَوۡمَ يَفِرُّ ٱلۡمَرۡءُ مِنۡ أَخِيهِ","وَأُمِّهِۦ وَأَبِيهِ","وَصَٰحِبَتِهِۦ وَبَنِيهِ","لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُمۡ يَوۡمَئِذٖ شَأۡنٌ يُغۡنِيهِ","وُجُوهٌ يَوۡمَئِذٖ مُّسۡفِرَةٌ","ضَاحِكَةٌ مُّسۡتَبۡشِرَةٌ","وَوُجُوهٌ يَوۡمَئِذٍ عَلَيۡهَا غَبَرَةٌ","تَرۡهَقُهَا قَتَرَةٌ","أُوْلَـٰٓئِكَ هُمُ ٱلۡكَفَرَةُ ٱلۡفَجَرَةُ"],"g":5759,"a":[["desert","😕🧑‍🦯","عبس النبي ﷺ وأعرض، لأن الرجل الأعمى جاءه.",2],["desert","😕🧑‍🦯","عبس النبي ﷺ وأعرض، لأن الرجل الأعمى جاءه.",-1],["desert","💭","وما يدريك؟ لعله يتطهّر من ذنوبه."],["desert","📖","أو يتذكّر فتنفعه النصيحة."],["desert","💰🙄","أما الغني الذي لا يهتم، فأنت تهتم به، وليس عليك شيء إن لم يتطهّر.",3],["desert","💰🙄","أما الغني الذي لا يهتم، فأنت تهتم به، وليس عليك شيء إن لم يتطهّر.",-1],["desert","💰🙄","أما الغني الذي لا يهتم، فأنت تهتم به، وليس عليك شيء إن لم يتطهّر.",-1],["desert","🏃🧑‍🦯","وأما الذي جاءك مسرعًا يريد الخير وهو يخاف الله، فأنت تنشغل عنه.",3],["desert","🏃🧑‍🦯","وأما الذي جاءك مسرعًا يريد الخير وهو يخاف الله، فأنت تنشغل عنه.",-1],["desert","🏃🧑‍🦯","وأما الذي جاءك مسرعًا يريد الخير وهو يخاف الله، فأنت تنشغل عنه.",-1],["light","📖✨","لا تفعل ذلك، فهذه الآيات تذكرة، فمن شاء تذكّر.",2],["light","📖✨","لا تفعل ذلك، فهذه الآيات تذكرة، فمن شاء تذكّر.",-1],["light","📜😇","القرآن مكتوب في صحف مكرّمة مرفوعة طاهرة، بأيدي ملائكة كرام أبرار.",4],["light","📜😇","القرآن مكتوب في صحف مكرّمة مرفوعة طاهرة، بأيدي ملائكة كرام أبرار.",-1],["light","📜😇","القرآن مكتوب في صحف مكرّمة مرفوعة طاهرة، بأيدي ملائكة كرام أبرار.",-1],["light","📜😇","القرآن مكتوب في صحف مكرّمة مرفوعة طاهرة، بأيدي ملائكة كرام أبرار.",-1],["desert","😟","هلك الإنسان الكافر، ما أشدّ كفره!"],["light","🌱","من أي شيء خلقه الله؟ خلقه من شيء صغير جدًا، وقدّره.",2],["light","🌱","من أي شيء خلقه الله؟ خلقه من شيء صغير جدًا، وقدّره.",-1],["desert","🛤️","ثم سهّل له طريق الحياة."],["desert","🪦","ثم أماته وجعل له قبرًا."],["sky","⏰","ثم إذا شاء أحياه يوم القيامة."],["desert","🚫","ولكن الإنسان لم يفعل كل ما أمره الله به."],["garden","🍽️👀","فلينظر الإنسان إلى طعامه، كيف خلقه الله؟"],["rain","🌧️","أنزلنا المطر بغزارة."],["earth","🌱","ثم شققنا الأرض بالنبات."],["garden","🌾🍇🥬","فأنبتنا فيها الحبوب، والعنب، والخضراوات.",2],["garden","🌾🍇🥬","فأنبتنا فيها الحبوب، والعنب، والخضراوات.",-1],["garden","🫒🌴","والزيتون والنخل."],["garden","🌳🌳","والحدائق ذات الأشجار الكثيرة."],["garden","🍎🌿","والفواكه، والعشب للحيوانات."],["garden","🐄","كل ذلك متاعًا لكم ولأنعامكم."],["storm","📯","فإذا جاءت الصيحة الشديدة يوم القيامة."],["storm","🏃","يوم يهرب الإنسان من أخيه، وأمه وأبيه، وزوجته وأولاده.",3],["storm","🏃","يوم يهرب الإنسان من أخيه، وأمه وأبيه، وزوجته وأولاده.",-1],["storm","🏃","يوم يهرب الإنسان من أخيه، وأمه وأبيه، وزوجته وأولاده.",-1],["storm","😰","لكل واحد منهم يومئذ همّ يكفيه."],["light","😊✨","وجوه المؤمنين يومئذ مضيئة، ضاحكة فرحة.",2],["light","😊✨","وجوه المؤمنين يومئذ مضيئة، ضاحكة فرحة.",-1],["storm","😞","ووجوه الكفار يومئذ عليها غبار وسواد، أولئك هم الكفرة الفجرة.",3],["storm","😞","ووجوه الكفار يومئذ عليها غبار وسواد، أولئك هم الكفرة الفجرة.",-1],["storm","😞","ووجوه الكفار يومئذ عليها غبار وسواد، أولئك هم الكفرة الفجرة.",-1]],"i":"سورة مكية. جاء رجل أعمى اسمه عبد الله بن أم مكتوم إلى النبي ﷺ يريد أن يتعلّم، وكان النبي ﷺ مشغولًا بدعوة كبار قريش، فعبس وأعرض عنه. فنزلت السورة تعلّمنا أن كل من يريد الخير مهم عند الله.","l":["كل إنسان يريد الخير مهم، لا نحكم على الناس بمالهم أو شكلهم","نهتم بمن يحب أن يتعلّم","طعامنا من نعم الله، فلنشكره","يوم القيامة كل إنسان مشغول بنفسه"],"q":[["من الذي جاء إلى النبي ﷺ يريد أن يتعلّم؟",["رجل أعمى","رجل غني","ملك"]],["ماذا نتعلم من السورة؟",["نحترم كل الناس","نهتم بالأغنياء فقط","نعبس في وجوه الناس"]],["من أين يأتي طعامنا؟",["من نعم الله","من لا شيء","من الدكان فقط"]]],"m":"كل الناس مهمّون، والأفضل عند الله من يحب الخير ويتعلّمه.","type":"meccan"},"79":{"n":79,"name":"النازعات","t":["وَٱلنَّـٰزِعَٰتِ غَرۡقٗا","وَٱلنَّـٰشِطَٰتِ نَشۡطٗا","وَٱلسَّـٰبِحَٰتِ سَبۡحٗا","فَٱلسَّـٰبِقَٰتِ سَبۡقٗا","فَٱلۡمُدَبِّرَٰتِ أَمۡرٗا","يَوۡمَ تَرۡجُفُ ٱلرَّاجِفَةُ","تَتۡبَعُهَا ٱلرَّادِفَةُ","قُلُوبٌ يَوۡمَئِذٖ وَاجِفَةٌ","أَبۡصَٰرُهَا خَٰشِعَةٌ","يَقُولُونَ أَءِنَّا لَمَرۡدُودُونَ فِي ٱلۡحَافِرَةِ","أَءِذَا كُنَّا عِظَٰمٗا نَّخِرَةٗ","قَالُواْ تِلۡكَ إِذٗا كَرَّةٌ خَاسِرَةٌ","فَإِنَّمَا هِيَ زَجۡرَةٌ وَٰحِدَةٌ","فَإِذَا هُم بِٱلسَّاهِرَةِ","هَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","إِذۡ نَادَىٰهُ رَبُّهُۥ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوًى","ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ","فَقُلۡ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ","وَأَهۡدِيَكَ إِلَىٰ رَبِّكَ فَتَخۡشَىٰ","فَأَرَىٰهُ ٱلۡأٓيَةَ ٱلۡكُبۡرَىٰ","فَكَذَّبَ وَعَصَىٰ","ثُمَّ أَدۡبَرَ يَسۡعَىٰ","فَحَشَرَ فَنَادَىٰ","فَقَالَ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ","فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلۡأٓخِرَةِ وَٱلۡأُولَىٰٓ","إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّمَن يَخۡشَىٰٓ","ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ بَنَىٰهَا","رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا","وَأَغۡطَشَ لَيۡلَهَا وَأَخۡرَجَ ضُحَىٰهَا","وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ","أَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعَىٰهَا","وَٱلۡجِبَالَ أَرۡسَىٰهَا","مَتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ","فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلۡكُبۡرَىٰ","يَوۡمَ يَتَذَكَّرُ ٱلۡإِنسَٰنُ مَا سَعَىٰ","وَبُرِّزَتِ ٱلۡجَحِيمُ لِمَن يَرَىٰ","فَأَمَّا مَن طَغَىٰ","وَءَاثَرَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا","فَإِنَّ ٱلۡجَحِيمَ هِيَ ٱلۡمَأۡوَىٰ","وَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ","فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ","يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَا","فِيمَ أَنتَ مِن ذِكۡرَىٰهَآ","إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ","إِنَّمَآ أَنتَ مُنذِرُ مَن يَخۡشَىٰهَا","كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَهَا لَمۡ يَلۡبَثُوٓاْ إِلَّا عَشِيَّةً أَوۡ ضُحَىٰهَا"],"g":5713,"a":[["sky","😇","يُقسم الله بالملائكة التي تنزع أرواح الكفار بشدة."],["sky","😇🕊️","وبالملائكة التي تأخذ أرواح المؤمنين برفق."],["sky","😇✨","وبالملائكة التي تنزل من السماء بأمر الله."],["sky","😇💨","وبالملائكة التي تسبق إلى تنفيذ أمر الله."],["sky","😇📜","وبالملائكة التي تدبّر ما أمرها الله به."],["storm","💥","يوم ترتجف الأرض بالنفخة الأولى."],["storm","📯","ثم تتبعها النفخة الثانية."],["storm","💓","قلوب الكفار يومئذ خائفة مضطربة."],["storm","😟","وأبصارهم ذليلة من الخوف."],["desert","💀❓","كان الكفار يقولون: هل سنعود أحياء بعد أن نموت وتصير عظامنا بالية؟",2],["desert","💀❓","كان الكفار يقولون: هل سنعود أحياء بعد أن نموت وتصير عظامنا بالية؟",-1],["desert","🙄","قالوا: إن رجعنا فستكون رجعة خاسرة."],["storm","📯👥","إنما هي صيحة واحدة، فإذا الناس كلهم أحياء على وجه الأرض.",2],["storm","📯👥","إنما هي صيحة واحدة، فإذا الناس كلهم أحياء على وجه الأرض.",-1],["desert","📖","هل جاءك يا محمد ﷺ خبر موسى عليه السلام؟"],["mountain","⛰️✨","حين ناداه ربه في الوادي المقدّس طُوى."],["desert","👑","قال الله له: اذهب إلى فرعون، فقد تجاوز الحد في الظلم."],["desert","💬","وقل له: هل تريد أن تتطهر من ذنوبك، وأدلّك على ربك فتخافه؟",2],["desert","💬","وقل له: هل تريد أن تتطهر من ذنوبك، وأدلّك على ربك فتخافه؟",-1],["desert","🐍✨","فأراه موسى المعجزة الكبرى: العصا تصير حيّة، واليد تخرج بيضاء."],["desert","🚫","فكذّب فرعون وعصى."],["desert","🏃","ثم أعرض يعمل ضد موسى."],["desert","📢👥","فجمع الناس وناداهم."],["desert","👑😤","فقال: أنا ربكم الأعلى!"],["sea","🌊👑","فعاقبه الله في الدنيا بالغرق، وفي الآخرة بالنار."],["light","💡","في قصة فرعون عبرة لمن يخاف الله."],["space","🌌❓","هل خلقكم أصعب أم خلق السماء؟ الله بناها."],["space","🌌","رفعها عالية وسوّاها بلا عيب."],["night","🌙☀️","وجعل ليلها مظلمًا، ونهارها مضيئًا."],["earth","🌍","والأرض بعد ذلك بسطها ومدّها."],["garden","💧🌱","وأخرج منها الماء والنبات."],["mountain","⛰️","والجبال ثبّتها."],["garden","🐑🌾","كل هذا متاعًا لكم ولأنعامكم."],["storm","💥","فإذا جاء يوم القيامة، الداهية الكبرى."],["light","🧠📒","يومها يتذكر الإنسان كل ما عمل."],["fire","🔥","وتظهر جهنم لكل من يراها."],["fire","🔥","فمن تجاوز الحد، وفضّل الدنيا على الآخرة، فإن مكانه جهنم.",3],["fire","🔥","فمن تجاوز الحد، وفضّل الدنيا على الآخرة، فإن مكانه جهنم.",-1],["fire","🔥","فمن تجاوز الحد، وفضّل الدنيا على الآخرة، فإن مكانه جهنم.",-1],["garden","🌳🏡","ومن خاف الوقوف أمام ربه، ومنع نفسه عن الشهوات الحرام، فإن مكانه الجنة.",2],["garden","🌳🏡","ومن خاف الوقوف أمام ربه، ومنع نفسه عن الشهوات الحرام، فإن مكانه الجنة.",-1],["desert","❓⏰","يسألك الكفار: متى يوم القيامة؟"],["sky","🤷","ليس عندك علم بموعدها."],["light","☝️","علمها عند الله وحده."],["sky","📢","إنما أنت تنذر من يخافها."],["sky","⏱️","يوم يرونها يظنون أنهم لم يعيشوا في الدنيا إلا مساءً أو صباحًا."]],"i":"سورة مكية. يُقسم الله فيها بالملائكة التي تنفّذ أمره، ليؤكد أن يوم القيامة حق. وفيها قصة موسى عليه السلام مع فرعون الذي تكبّر وقال: أنا ربكم الأعلى، فأغرقه الله.","l":["يوم القيامة حق، ولا يعلم موعده إلا الله","الظلم والتكبر نهايتهما الخسارة مثل فرعون","من خاف الله ومنع نفسه عن الحرام فله الجنة","خلق السماء والأرض دليل على قدرة الله"],"q":[["من الذي قال: أنا ربكم الأعلى؟",["فرعون","موسى","هارون"]],["ماذا كانت نهاية فرعون؟",["أغرقه الله","صار ملكًا للأبد","هرب"]],["من يعلم موعد يوم القيامة؟",["الله وحده","الناس","العلماء"]]],"m":"التكبّر يُهلك صاحبه، ومن خاف الله فاز بالجنة.","type":"meccan"},"78":{"n":78,"name":"النبإ","t":["عَمَّ يَتَسَآءَلُونَ","عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ","ٱلَّذِي هُمۡ فِيهِ مُخۡتَلِفُونَ","كَلَّا سَيَعۡلَمُونَ","ثُمَّ كَلَّا سَيَعۡلَمُونَ","أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَٰدٗا","وَٱلۡجِبَالَ أَوۡتَادٗا","وَخَلَقۡنَٰكُمۡ أَزۡوَٰجٗا","وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا","وَجَعَلۡنَا ٱلَّيۡلَ لِبَاسٗا","وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشٗا","وَبَنَيۡنَا فَوۡقَكُمۡ سَبۡعٗا شِدَادٗا","وَجَعَلۡنَا سِرَاجٗا وَهَّاجٗا","وَأَنزَلۡنَا مِنَ ٱلۡمُعۡصِرَٰتِ مَآءٗ ثَجَّاجٗا","لِّنُخۡرِجَ بِهِۦ حَبّٗا وَنَبَاتٗا","وَجَنَّـٰتٍ أَلۡفَافًا","إِنَّ يَوۡمَ ٱلۡفَصۡلِ كَانَ مِيقَٰتٗا","يَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَتَأۡتُونَ أَفۡوَاجٗا","وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتۡ أَبۡوَٰبٗا","وَسُيِّرَتِ ٱلۡجِبَالُ فَكَانَتۡ سَرَابًا","إِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادٗا","لِّلطَّـٰغِينَ مَـَٔابٗا","لَّـٰبِثِينَ فِيهَآ أَحۡقَابٗا","لَّا يَذُوقُونَ فِيهَا بَرۡدٗا وَلَا شَرَابًا","إِلَّا حَمِيمٗا وَغَسَّاقٗا","جَزَآءٗ وِفَاقًا","إِنَّهُمۡ كَانُواْ لَا يَرۡجُونَ حِسَابٗا","وَكَذَّبُواْ بِـَٔايَٰتِنَا كِذَّابٗا","وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ كِتَٰبٗا","فَذُوقُواْ فَلَن نَّزِيدَكُمۡ إِلَّا عَذَابًا","إِنَّ لِلۡمُتَّقِينَ مَفَازًا","حَدَآئِقَ وَأَعۡنَٰبٗا","وَكَوَاعِبَ أَتۡرَابٗا","وَكَأۡسٗا دِهَاقٗا","لَّا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا كِذَّـٰبٗا","جَزَآءٗ مِّن رَّبِّكَ عَطَآءً حِسَابٗا","رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلرَّحۡمَٰنِۖ لَا يَمۡلِكُونَ مِنۡهُ خِطَابٗا","يَوۡمَ يَقُومُ ٱلرُّوحُ وَٱلۡمَلَـٰٓئِكَةُ صَفّٗاۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَقَالَ صَوَابٗا","ذَٰلِكَ ٱلۡيَوۡمُ ٱلۡحَقُّۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا","إِنَّآ أَنذَرۡنَٰكُمۡ عَذَابٗا قَرِيبٗا يَوۡمَ يَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا"],"g":5673,"a":[["desert","🗣️❓","عن أي شيء يسأل الكفار بعضهم بعضًا؟"],["desert","📰","يسألون عن الخبر العظيم: يوم القيامة."],["desert","🤷","الذي اختلفوا فيه: بعضهم يصدّق وبعضهم يكذّب."],["sky","⚠️","ليس الأمر كما يظنون، سيعرفون الحقيقة قريبًا، ثم سيعرفونها مرة أخرى.",2],["sky","⚠️","ليس الأمر كما يظنون، سيعرفون الحقيقة قريبًا، ثم سيعرفونها مرة أخرى.",-1],["earth","🌍","ألم نجعل الأرض ممهّدة مثل الفراش لتعيشوا عليها؟"],["mountain","⛰️","والجبال ثابتة مثل الأوتاد التي تثبّت الخيمة."],["garden","👫","وخلقناكم أزواجًا: ذكرًا وأنثى."],["night","😴","وجعلنا النوم راحة لكم."],["night","🌙","وجعلنا الليل يغطّيكم بظلامه مثل اللباس."],["day","☀️👷","وجعلنا النهار وقتًا للعمل وطلب الرزق."],["space","🌌","وبنينا فوقكم سبع سماوات قوية."],["day","☀️","وجعلنا الشمس سراجًا منيرًا حارًّا."],["rain","🌧️","وأنزلنا من السحاب ماء المطر الكثير."],["garden","🌾🌱","لنُخرج به الحبوب والنباتات."],["garden","🌳🌳","والبساتين الكثيرة الأشجار."],["sky","⏳","يوم القيامة له موعد محدّد عند الله."],["sky","📯👥","يوم يُنفخ في الصور فيأتي الناس جماعات جماعات."],["space","🚪","وتنشقّ السماء فتصير أبوابًا."],["desert","⛰️💨","وتتحرك الجبال وتتطاير حتى تصير مثل السراب."],["fire","🔥","جهنم تنتظر الظالمين الذين تجاوزوا حدود الله، فهي مكانهم.",2],["fire","🔥","جهنم تنتظر الظالمين الذين تجاوزوا حدود الله، فهي مكانهم.",-1],["fire","⏳","يبقون فيها مددًا طويلة جدًا."],["fire","🥵","لا يجدون فيها شيئًا باردًا ولا شرابًا يُطفئ عطشهم، إلا ماءً شديد الحرارة.",2],["fire","🥵","لا يجدون فيها شيئًا باردًا ولا شرابًا يُطفئ عطشهم، إلا ماءً شديد الحرارة.",-1],["light","⚖️","جزاءً عادلًا على أعمالهم."],["fire","🙈","لأنهم كانوا لا يخافون الحساب."],["fire","🚫📖","وكذّبوا بآيات الله تكذيبًا شديدًا."],["light","📒✍️","وكل شيء فعلوه مكتوب عند الله."],["fire","🔥","فذوقوا العذاب، فلن نزيدكم إلا عذابًا."],["garden","🏆","أما المتقون فلهم الفوز والنجاة."],["garden","🍇🌴","لهم حدائق وأعناب."],["garden","💐","ولهم أزواج طيّبات متساويات في العمر."],["garden","🥤","وكأس مملوءة بشراب لذيذ."],["garden","🤫","لا يسمعون في الجنة كلامًا سيئًا ولا كذبًا."],["garden","🎁","جزاءً من ربك، وعطاءً كثيرًا."],["space","👑","الله ربّ السماوات والأرض، الرحمن، لا يستطيع أحد أن يتكلم أمامه إلا بإذنه."],["light","😇","يوم يقف جبريل والملائكة صفوفًا، لا يتكلم أحد إلا من أذن له الرحمن وقال الصواب."],["sky","🛤️","ذلك اليوم حق، فمن شاء فليعمل الخير ليرجع إلى ربه."],["sky","📜","حذّرناكم من عذاب قريب، يوم يرى كل إنسان ما عمل، ويتمنى الكافر لو كان ترابًا."]],"i":"سورة مكية. كان الكفار يتساءلون ويتجادلون عن يوم القيامة: هل هو حق؟ فأخبرهم الله بالخبر العظيم، وذكّرهم بنعمه الكثيرة التي تدل على أنه قادر على أن يبعث الناس بعد موتهم.","l":["الله قادر على أن يبعثنا بعد الموت","نِعم الله حولنا كثيرة: الأرض والجبال والنوم والمطر","كل أعمالنا مكتوبة، فلنعمل الخير","الجنة جزاء المتقين"],"q":[["عن ماذا كان الكفار يتساءلون؟",["يوم القيامة","المطر","الطعام"]],["ماذا جعل الله الجبال؟",["أوتادًا تثبّت الأرض","بحارًا","أنهارًا"]],["لماذا جعل الله لنا النوم؟",["راحة لنا","للعب","للأكل"]]],"m":"الله الذي خلق لنا كل هذه النعم قادر على أن يبعثنا، فلنستعد ليوم القيامة بالعمل الصالح.","type":"meccan"}};
